	END

	IF NOT EXISTS (SELECT 1 FROM [dbo].[LineOfBusinessLU] WHERE LineOfBusinessID = 1008)
	BEGIN
		INSERT INTO [dbo].[LineOfBusinessLU] (LineOfBusinessID, LineOfBusiness)
			VALUES (1008, 'Mission Solutions (MsnSln)')
	END
END
