DECLARE @NewWorkspaceID int
INSERT INTO [dbo].[Workspace]
           ([UpdateDT]
           ,[WorkspaceName]
           ,[WorkspaceShortName]
           ,[WorkspaceStateID]
           ,[ContractStartDate]
           ,[ContractEndDate]
           ,[ProposalSubmitDate]
           ,[WorkspaceDescription]
           ,[ProposalTypeID]
           ,[CostVolumeLeadPricerUserID]
           ,[RFPNumber]
           ,[TemplateID]
           ,[ContainsOCI]
           ,[CreatedByETIUserID]
           ,[AllowSearch]
           ,[ResourceListID]
           ,[PerformingOrganizationListID]
           ,[PerformingOrganizationChangeFlag]
           ,[TrackingNumber]
           ,[ContainsTemplate]
           ,[NumProPricerExport]
           ,[ProposalStatusID]
           ,[StatusComment]
           ,[DTSAutoCalculateID]
           ,[CalculateLaborCostFlag]
           ,[ProductLineID]
           ,[BOEExportSortByID]
           ,[SegmentID]
           ,[LineOfBusinessID]
           ,[ProposalClassID]
		   ,[ProposalTitle]
		   ,[IsDeleted]
		   ,[DateDeleted]
		   ,[ResourcePrecision]
		   ,[RecalculationStartedDate]
		   ,[RestrictDTS]
		   ,[CostPrecision]
           )
SELECT [UpdateDT]
      ,@WorkspaceName--[WorkspaceName]
      ,@WorkspaceShortName--[WorkspaceShortName]
      ,[WorkspaceStateID]
      ,[ContractStartDate]
      ,[ContractEndDate]
      ,[ProposalSubmitDate]
      ,[WorkspaceDescription]
      ,[ProposalTypeID]
      ,[CostVolumeLeadPricerUserID]
      ,[RFPNumber]
      ,[TemplateID]
      ,[ContainsOCI]
      ,[CreatedByETIUserID]
      ,[AllowSearch]
      ,@ResourceListID--[ResourceListID]
      ,@PerformingOrganizationListID--[PerformingOrganizationListID]
      --,[ResourceChangeFlag]
      ,[PerformingOrganizationChangeFlag]
      ,[TrackingNumber]
      ,[ContainsTemplate]
      ,[NumProPricerExport]
      ,[ProposalStatusID]
      ,[StatusComment]
      ,CASE WHEN getDate() > = @RestrictDTSDate THEN 1 /*NONE*/ ELSE  [DTSAutoCalculateID] END AS  [DTSAutoCalculateID]
      ,[CalculateLaborCostFlag]
      ,CASE 
			WHEN [ProductLineID] = (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'Defense')   THEN (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'D&IS')
			WHEN [ProductLineID] = (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'National')  THEN (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'D&IS')
		ELSE [ProductLineID]
		END		
      ,[BOEExportSortByID]
      ,[SegmentID]
      ,[LineOfBusinessID]
      ,[ProposalClassID]
	  ,[ProposalTitle]
      ,[IsDeleted]
	  ,[DateDeleted]  
	  ,[ResourcePrecision]
	  ,[RecalculationStartedDate]
      ,CASE WHEN getDate() > = @RestrictDTSDate THEN 1/*RESTRICT*/ ELSE  [RestrictDTS] END AS  [RestrictDTS]
	  ,[CostPrecision]
  FROM [dbo].[Workspace]
WHERE WorkspaceID = @WorkspaceID

SELECT @NewWorkspaceID = SCOPE_IDENTITY()

