/****** Object:  Table [dbo].[ODCType]    Script Date: 05/15/2012 11:09:06 ******/
DECLARE @ODCType TABLE 
(
	[ODCTypeID] [int] NOT NULL,
	[UpdateDT] [datetime2](7) NOT NULL,
	[ResourceID] [int] NULL,
	[PerformingOrganizationID] [int] NULL,
	[ODCTypeStartDate] [date] NOT NULL,
	[ODCTypeEndDate] [date] NULL,
	[SpreadCurveID] [int] NOT NULL,
	[ODCTypeCost] [decimal](12, 2) NULL,
	[ODCTaskElementID] [int] NOT NULL,
	Processed bit DEFAULT 0,
	NewODCTypeID int,
	NewResourceID int,
	NewPerformingOrganizationID int,
	NewODCTaskElementID int
)
INSERT INTO	@ODCType
SELECT O.[ODCTypeID]
      ,O.[UpdateDT]
      ,O.[ResourceID]
      ,O.[PerformingOrganizationID]
      ,O.[ODCTypeStartDate]
      ,O.[ODCTypeEndDate]
      ,O.[SpreadCurveID]
      ,O.[ODCTypeCost]
      ,O.[ODCTaskElementID]
      ,0
      ,NULL
      ,R.NewResourceID
      ,PO.NewPerformingOrganizationID
      ,TE.NewODCTaskElementID
  FROM [dbo].[ODCType] O
--	INNER JOIN @ResourceMapping R ON O.ResourceID = R.OriginalResourceID
--	INNER JOIN @POMapping P ON O.PerformingOrganizationID = P.OriginalPOID
	INNER JOIN @ODCTaskElement TE ON O.ODCTaskElementID = TE.ODCTaskElementID
	LEFT OUTER JOIN @Resource R ON O.ResourceID = R.ResourceID
	LEFT OUTER JOIN @PerformingOrganization PO ON O.PerformingOrganizationID = PO.PerformingOrganizationID	

DECLARE @ODCTypeID int
WHILE EXISTS (SELECT 1 FROM @ODCType WHERE Processed = 0)
BEGIN
SELECT TOP 1 @ODCTypeID = ODCTypeID FROM @ODCType WHERE Processed = 0
INSERT INTO [dbo].[ODCType]
           ([UpdateDT]
           ,[ResourceID]
           ,[PerformingOrganizationID]
           ,[ODCTypeStartDate]
           ,[ODCTypeEndDate]
           ,[SpreadCurveID]
           ,[ODCTypeCost]
           ,[ODCTaskElementID])
SELECT [UpdateDT]
      ,CASE
		WHEN NewResourceID IS NOT NULL THEN NewResourceID
		ELSE [ResourceID]
		END AS ResourceID

      ,CASE
		WHEN NewPerformingOrganizationID IS NOT NULL THEN NewPerformingOrganizationID
		ELSE [PerformingOrganizationID]
		END AS PerformingOrganizationID
	
/*      ,NewPerformingOrganizationID--[PerformingOrganizationID]*/

      ,[ODCTypeStartDate]
      ,[ODCTypeEndDate]
      ,[SpreadCurveID]
      ,[ODCTypeCost]
      ,NewODCTaskElementID--[ODCTaskElementID]
  FROM @ODCType
WHERE ODCTypeID = @ODCTypeID  


UPDATE @ODCType
SET NewODCTypeID = SCOPE_IDENTITY(),
	Processed = 1
WHERE ODCTypeID = @ODCTypeID  

END

