	  ,TE.[SortOrderID]
  FROM [dbo].[BOETaskElement] TE
	INNER JOIN @BOE B ON TE.BOEID = B.BOEID

/*
Fix Workspace Variables in MOQ Equations
*/
DECLARE @WSVar TABLE
(
MOQHoursEquation varchar (500),
Original varchar(100),
Updated varchar(100),
OriginalID int,
UpdatedID int,
BOETaskElementID int
)
INSERT INTO @WSVar (MOQHoursEquation, BOETaskElementID)
SELECT MOQHoursEquation, BOETaskElementID  
FROM @BOETaskElement 
WHERE MOQHoursEquation LIKE '%<WSVAR:%'

WHILE EXISTS (SELECT 1 FROM @WSVar WHERE MOQHoursEquation LIKE '%<WSVAR:%')
BEGIN
UPDATE @WSVar
SET Original = 
SUBSTRING 
	(
		MOQHoursEquation,
		CHARINDEX ('<WSVAR:',MOQHoursEquation),
		(CHARINDEX ('>',MOQHoursEquation) - CHARINDEX ('<WSVAR:',MOQHoursEquation) + 1)
	)
	


UPDATE @WSVar
SET OriginalID =
 REPLACE (RIGHT (Original,
	(LEN (Original) - CHARINDEX (':',Original))),
	'>', '')


UPDATE @WSVar
SET UpdatedID = WS.NewWorkspaceVariableID
FROM @WSVar t
	INNER JOIN @WorkspaceVariable WS ON t.OriginalID = WS.WorkspaceVariableID


UPDATE @WSVar
SET Updated = 
REPLACE (Original, OriginalID, UpdatedID) 


UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.Original, V.Updated)
FROM @BOETaskElement TE
	INNER JOIN @WSVar V ON TE.BOETaskElementID = V. BOETaskElementID

UPDATE @WSVar 
SET MOQHoursEquation = REPLACE (MOQHoursEquation, Original, '')

END

/*Only copy DTS until this time*/
IF (SELECT getDate())  <=  @RestrictDTSDate

BEGIN

/*
Fix DTS Variables in MOQ Equations
*/
DECLARE @DTSVar TABLE
(
MOQHoursEquation varchar (500),
OriginalBOE varchar(100),
UpdatedBOE varchar(100),
OriginalBOEID int,
UpdatedBOEID int,

OriginalRegionPartA varchar(100),
UpdatedRegionPartA varchar(100),
OriginalRegionPartAID int,
UpdatedRegionPartAID int,


OriginalRegionPartB varchar(100),
UpdatedRegionPartB varchar(100),
OriginalRegionPartBID int,
UpdatedRegionPartBID int,


BOETaskElementID int
)
INSERT INTO @DTSVar (MOQHoursEquation, BOETaskElementID)
SELECT MOQHoursEquation, BOETaskElementID  
FROM @BOETaskElement 
WHERE 
	MOQHoursEquation LIKE '%<DTSALLBOEVAR%' AND
		(
			MOQHoursEquation LIKE '%<DTSREGIONVAR%' OR
			MOQHoursEquation LIKE '%:REGION:%' 
		)
		


IF EXISTS (SELECT 1 FROM @DTSVar)
BEGIN
/*boe*/

UPDATE @DTSVar
SET OriginalBOE = 
SUBSTRING 
	(
		MOQHoursEquation,
		CHARINDEX ('<DTSALLBOEVAR:',MOQHoursEquation),
		(CHARINDEX ('>',MOQHoursEquation) - CHARINDEX ('<DTSALLBOEVAR:',MOQHoursEquation) + 1)
	)
	

 
UPDATE @DTSVar
SET OriginalBOE = 
SUBSTRING 
	(
		OriginalBOE,
		CHARINDEX ('<DTSALLBOEVAR:',OriginalBOE),
		(CHARINDEX (':REGION',OriginalBOE) - CHARINDEX ('<DTSALLBOEVAR:',OriginalBOE))
	)

	
UPDATE @DTSVar
SET OriginalBOEID =
 REPLACE (RIGHT (OriginalBOE,
	(LEN (OriginalBOE) - CHARINDEX (':',OriginalBOE))),
	'>', '')




/*DTSREGION*/
UPDATE @DTSVar
SET OriginalRegionPartA = 
RIGHT (MOQHoursEquation, (LEN(MOQHoursEquation) - CHARINDEX ('<DTSREGIONVAR:',MOQHoursEquation))+1)


UPDATE @DTSVar
SET OriginalRegionPartA = 
SUBSTRING 
	(
		OriginalRegionPartA,
		CHARINDEX ('<DTSREGIONVAR:',OriginalRegionPartA),
		(CHARINDEX ('>',OriginalRegionPartA) - CHARINDEX ('<DTSREGIONVAR:',OriginalRegionPartA) + 1)
	)

 

UPDATE @DTSVar
SET OriginalRegionPartAID =
 REPLACE (RIGHT (OriginalRegionPartA,
	(LEN (OriginalRegionPartA) - CHARINDEX (':',OriginalRegionPartA))),
	'>', '')




/*DTSREGION PART B*/
UPDATE @DTSVar
SET OriginalRegionPartB = 
RIGHT (MOQHoursEquation, (LEN(MOQHoursEquation) - CHARINDEX ('REGION:',MOQHoursEquation))+1)


UPDATE @DTSVar
SET OriginalRegionPartB = 
SUBSTRING 
	(
		OriginalRegionPartB,
		CHARINDEX ('REGION:',OriginalRegionPartB),
		(CHARINDEX ('>',OriginalRegionPartB) - CHARINDEX ('REGION:',OriginalRegionPartB) + 1)
	)
 

UPDATE @DTSVar
SET OriginalRegionPartBID =
 REPLACE (RIGHT (OriginalRegionPartB,
	(LEN (OriginalRegionPartB) - CHARINDEX (':',OriginalRegionPartB))),
	'>', '')


UPDATE @DTSVar
SET UpdatedBOEID = B.NewBOEID
FROM @DTSVar D
	INNER JOIN @BOE B ON D.OriginalBOEID = B.BOEID


UPDATE @DTSVar
SET UpdatedRegionPartAID = R.NewWorkspaceRegionDTSID
FROM @DTSVar D
	INNER JOIN @WorkspaceRegionDTS R ON D.OriginalRegionPartAID = R.WorkspaceRegionDTSID


UPDATE @DTSVar
SET UpdatedRegionPartBID = R.NewWorkspaceRegionDTSID
FROM @DTSVar D
	INNER JOIN @WorkspaceRegionDTS R ON D.OriginalRegionPartBID = R.WorkspaceRegionDTSID


UPDATE @DTSVar
SET
UpdatedBOE = REPLACE (OriginalBOE, OriginalBOEID, UpdatedBOEID),
UpdatedRegionPartA = REPLACE (OriginalRegionPartA, OriginalRegionPartAID, UpdatedRegionPartAID),
UpdatedRegionPartB = REPLACE (OriginalRegionPartB, OriginalRegionPartBID, UpdatedRegionPartBID)


UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.OriginalBOE, V.UpdatedBOE)
FROM @BOETaskElement TE
	INNER JOIN @DTSVar V ON TE.BOETaskElementID = V. BOETaskElementID



UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.OriginalRegionPartA, V.UpdatedRegionPartA)
FROM @BOETaskElement TE
	INNER JOIN @DTSVar V ON TE.BOETaskElementID = V. BOETaskElementID


UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.OriginalRegionPartB, V.UpdatedRegionPartB)
FROM @BOETaskElement TE
	INNER JOIN @DTSVar V ON TE.BOETaskElementID = V. BOETaskElementID

END


/*PROCESS CLIN*/

/*
Fix DTS Variables in MOQ Equations - <DTSCLINVAR:3830:REGION:194> * <DTSREGIONVAR:194>
*/
DECLARE @DTSVarCLIN TABLE
(
MOQHoursEquation varchar (500),

OriginalCLIN varchar(100),
UpdatedCLIN varchar(100),
OriginalCLINID int,
UpdatedCLINID int,

OriginalRegionPartA varchar(100),
UpdatedRegionPartA varchar(100),
OriginalRegionPartAID int,
UpdatedRegionPartAID int,


OriginalRegionPartB varchar(100),
UpdatedRegionPartB varchar(100),
OriginalRegionPartBID int,
UpdatedRegionPartBID int,


BOETaskElementID int
)

INSERT INTO @DTSVarCLIN (MOQHoursEquation, BOETaskElementID)
SELECT MOQHoursEquation, BOETaskElementID  
FROM @BOETaskElement 
WHERE 
	MOQHoursEquation LIKE '%<DTSCLINVAR%' AND
		(
			MOQHoursEquation LIKE '%<DTSREGIONVAR%' OR
			MOQHoursEquation LIKE '%:REGION:%' 
		)
		


IF EXISTS (SELECT 1 FROM @DTSVarCLIN)
BEGIN
/*CLIN*/

UPDATE @DTSVarCLIN
SET OriginalCLIN = 
SUBSTRING 
	(
		MOQHoursEquation,
		CHARINDEX ('<DTSCLINVAR:',MOQHoursEquation),
		(CHARINDEX ('>',MOQHoursEquation) - CHARINDEX ('<DTSCLINVAR:',MOQHoursEquation) + 1)
	)
	

 
UPDATE @DTSVarCLIN
SET OriginalCLIN = 
SUBSTRING 
	(
		OriginalCLIN,
		CHARINDEX ('<DTSCLINVAR:',OriginalCLIN),
		(CHARINDEX (':REGION',OriginalCLIN) - CHARINDEX ('<DTSCLINVAR:',OriginalCLIN))
	)

	
UPDATE @DTSVarCLIN
SET OriginalCLINID =
 REPLACE (RIGHT (OriginalCLIN,
	(LEN (OriginalCLIN) - CHARINDEX (':',OriginalCLIN))),
	'>', '')




/*DTSREGION*/
UPDATE @DTSVarCLIN
SET OriginalRegionPartA = 
RIGHT (MOQHoursEquation, (LEN(MOQHoursEquation) - CHARINDEX ('<DTSREGIONVAR:',MOQHoursEquation))+1)


UPDATE @DTSVarCLIN
SET OriginalRegionPartA = 
SUBSTRING 
	(
		OriginalRegionPartA,
		CHARINDEX ('<DTSREGIONVAR:',OriginalRegionPartA),
		(CHARINDEX ('>',OriginalRegionPartA) - CHARINDEX ('<DTSREGIONVAR:',OriginalRegionPartA) + 1)
	)

 

UPDATE @DTSVarCLIN
SET OriginalRegionPartAID =
 REPLACE (RIGHT (OriginalRegionPartA,
	(LEN (OriginalRegionPartA) - CHARINDEX (':',OriginalRegionPartA))),
	'>', '')




/*DTSREGION PART B*/
UPDATE @DTSVarCLIN
SET OriginalRegionPartB = 
RIGHT (MOQHoursEquation, (LEN(MOQHoursEquation) - CHARINDEX ('REGION:',MOQHoursEquation))+1)


UPDATE @DTSVarCLIN
SET OriginalRegionPartB = 
SUBSTRING 
	(
		OriginalRegionPartB,
		CHARINDEX ('REGION:',OriginalRegionPartB),
		(CHARINDEX ('>',OriginalRegionPartB) - CHARINDEX ('REGION:',OriginalRegionPartB) + 1)
	)
 

UPDATE @DTSVarCLIN
SET OriginalRegionPartBID =
 REPLACE (RIGHT (OriginalRegionPartB,
	(LEN (OriginalRegionPartB) - CHARINDEX (':',OriginalRegionPartB))),
	'>', '')

	
UPDATE @DTSVarCLIN
SET UpdatedCLINID = B.NewCLINID
FROM @DTSVarCLIN D
	INNER JOIN @CLIN B ON D.OriginalCLINID = B.CLINID


UPDATE @DTSVarCLIN
SET UpdatedRegionPartAID = R.NewWorkspaceRegionDTSID
FROM @DTSVarCLIN D
	INNER JOIN @WorkspaceRegionDTS R ON D.OriginalRegionPartAID = R.WorkspaceRegionDTSID


UPDATE @DTSVarCLIN
SET UpdatedRegionPartBID = R.NewWorkspaceRegionDTSID
FROM @DTSVarCLIN D
	INNER JOIN @WorkspaceRegionDTS R ON D.OriginalRegionPartBID = R.WorkspaceRegionDTSID


UPDATE @DTSVarCLIN
SET
UpdatedCLIN = REPLACE (OriginalCLIN, OriginalCLINID, UpdatedCLINID),
UpdatedRegionPartA = REPLACE (OriginalRegionPartA, OriginalRegionPartAID, UpdatedRegionPartAID),
UpdatedRegionPartB = REPLACE (OriginalRegionPartB, OriginalRegionPartBID, UpdatedRegionPartBID)


UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.OriginalCLIN, V.UpdatedCLIN)
FROM @BOETaskElement TE
	INNER JOIN @DTSVarCLIN V ON TE.BOETaskElementID = V.BOETaskElementID



UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.OriginalRegionPartA, V.UpdatedRegionPartA)
FROM @BOETaskElement TE
	INNER JOIN @DTSVarCLIN V ON TE.BOETaskElementID = V.BOETaskElementID


UPDATE @BOETaskElement
SET MOQHoursEquation = 
REPLACE (TE.MOQHoursEquation, V.OriginalRegionPartB, V.UpdatedRegionPartB)
FROM @BOETaskElement TE
	INNER JOIN @DTSVarCLIN V ON TE.BOETaskElementID = V.BOETaskElementID

END

END

DECLARE @BOETaskElementID int
WHILE EXISTS (SELECT 1 FROM @BOETaskElement WHERE Processed = 0)
BEGIN
SELECT TOP 1 @BOETaskElementID = BOETaskElementID FROM @BOETaskElement WHERE Processed = 0
INSERT INTO [dbo].[BOETaskElement]
           ([UpdateDT]
           ,[TaskID]
           ,[TaskTitle]
           ,[TaskDescription]
           ,[TaskStartDate]
           ,[TaskEndDate]
           ,[MOQHoursEquation]
           ,[MOQCostEquation]
           ,[MOQText]
           ,[MOQTypeID]
           ,[BOEID]
           ,[LaborTypeWarningFlag]
           ,[IMS_ID]
           ,[TaskElementTypeID]
		   ,[SortOrderID]
		   )
 SELECT [UpdateDT]
      ,[TaskID]
      ,[TaskTitle]
      ,[TaskDescription]
      ,[TaskStartDate]
      ,[TaskEndDate]
      ,[MOQHoursEquation]
      ,[MOQCostEquation]
      ,[MOQText]
      ,[MOQTypeID]
      ,NewBOEID--[BOEID]
      ,[LaborTypeWarningFlag]
      ,[IMS_ID]
      ,[TaskElementTypeID]
	  ,[SortOrderID]
  FROM @BOETaskElement
WHERE BOETaskElementID = @BOETaskElementID
	AND
	(
		/*Only copy DTS until this time*/
		(
			/*If less than this date, still copy*/
			getDate()  <=  @RestrictDTSDate
		) OR 
		( 
			/*If greater than this date, do not copy DTS*/
			getDate()  >=  @RestrictDTSDate AND
			[TaskElementTypeID] <>  3	/*DTS*/
		)
	)


UPDATE @BOETaskElement
SET NewBOETaskElementID = SCOPE_IDENTITY(),
	Processed = 1
WHERE BOETaskElementID = @BOETaskElementID

END	

