		  ,(SELECT COUNT (*) FROM [dbo].[BOE] WHERE WorkspaceID = @CopyFromWorkspaceID) AS [NumOfBOEs]
		  ,@CreateDate
	  FROM [dbo].[Workspace] W
		INNER JOIN [dbo].[ProposalTypeLU] PT ON W.ProposalTypeID = PT.ProposalTypeID
