		LEFT OUTER JOIN [dbo].[LineOfBusiness] LOB ON W.LineOfBusinessID = LOB.LineOfBusinessID
	  WHERE WorkspaceID = @CopyFromWorkspaceID



		INSERT INTO [dbo].[WorkspaceCopyTarget]
