           ,[IsDeleted]
           ,[DateDeleted]
		   ,[ProposalType]
		   ,[ProductLineName]
		   ,[ProductLineLongName]
		   ,[LineOfBusinessName]
		   ,[LineOfBusinessLongName]
		   ,[NumOfBOEs]
		   ,[CreateDate]
		   )

	SELECT W.[WorkspaceID]
		  ,W.[UpdateDT]
