INNER JOIN dbo.Workspace WS ON WS.ResourceListID = R.ResourceListID
WHERE
WS.WorkspaceID = @WorkspaceID	

INSERT INTO [version].[Workspace]
([WorkspaceID]
,[WorkspaceName]
,[WorkspaceShortName]
,[WorkspaceStateID]
,[ContractStartDate]
,[ContractEndDate]
,[ProposalSubmitDate]
,[WorkspaceDescription]
,[ProposalTypeID]
,[CostVolumeLeadPricerUserID]
,[RFPNumber]
,[TemplateID]
,[ContainsOCI]
,[CreatedByETIUserID]
,[AllowSearch]
,[ResourceListID]
,[PerformingOrganizationListID]
--,[ResourceChangeFlag]
,[PerformingOrganizationChangeFlag]
,[TrackingNumber]
,[ContainsTemplate]
,[NumProPricerExport]
,[ProposalStatusID]
,[StatusComment]
,[UpdateDT]
,[DTSAutoCalculateID]
,[CalculateLaborCostFlag]
,[VersionID]
,[ProductLineID]/*WI8535*/
/*Remove Code for 7681 ,[LaborPrecisionID]*/
/*WI9756*/
,[BOEExportSortByID]
,[SegmentID]
,[LineOfBusinessID]
,[ProposalClassID]
,[ProposalTitle]
,[IsDeleted]
,[DateDeleted]
,[ResourcePrecision]
,[RecalculationStartedDate]
,[RestrictDTS]
,[CostPrecision]
)
SELECT [WorkspaceID]
,[WorkspaceName]
,[WorkspaceShortName]
,[WorkspaceStateID]
,[ContractStartDate]
,[ContractEndDate]
,[ProposalSubmitDate]
,[WorkspaceDescription]
,[ProposalTypeID]
,[CostVolumeLeadPricerUserID]
,[RFPNumber]
,[TemplateID]
,[ContainsOCI]
,[CreatedByETIUserID]
,[AllowSearch]
,[ResourceListID]
,[PerformingOrganizationListID]
,[PerformingOrganizationChangeFlag]
,[TrackingNumber]
,[ContainsTemplate]
,[NumProPricerExport]
,[ProposalStatusID]
,[StatusComment]
,[UpdateDT]
,[DTSAutoCalculateID]
,[CalculateLaborCostFlag]
,@VersionID
/*Remove Code for 7681 ,[LaborPrecisionID]*/
      ,CASE 
			WHEN [ProductLineID] = (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'Defense')   THEN (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'D&IS')
			WHEN [ProductLineID] = (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'National')  THEN (SELECT ProductLineID FROM dbo.ProductLine WHERE ProductLineName = 'D&IS')
		ELSE [ProductLineID]
		END	
,[BOEExportSortByID]
,[SegmentID]
,[LineOfBusinessID]
,[ProposalClassID]
,[ProposalTitle]
,[IsDeleted]
,[DateDeleted]
,[ResourcePrecision]
,[RecalculationStartedDate]
,[RestrictDTS]
,[CostPrecision]
FROM [dbo].[Workspace]
WHERE WorkspaceID = @WorkspaceID

