INSERT INTO [version].[Metric]
([MetricID]
,[MetricTitle]
,[Discipline]
,[MetricAdminGroupID]
,[SourceProgramLongName]
,[SourceProgramShortName]
,[MajorComponentCharacteristic]
,[ProgramMilestone]
,[UsageID]
,[LaborSourceID]
,[Size]
,[LaborHours]
,[AverageLaborType]
,[MOQEquation]
,[MOQTypeID]
,[MOQText]
,[MetricStatusID]
,[MetricOwnerETIUserID]
,[MetricMinedETIUserID]
,[MetricMinedDate]
,[MetricValidatedETIUserID]
,[MetricValidatedDate]
,[MetricSupportingDataETIUserID]
,[MetricSupportingDataDate]
,[CustomerApprovalRequiredFlag]
,[DataSourceLocation]
,[MetricInUse]
,[UpdatedByETIUserID]
,[UpdateDT]
,[VersionID]
,[LaborHourMetric]
)
SELECT M.[MetricID]
      ,M.[MetricTitle]
      ,M.[Discipline]
      ,M.[MetricAdminGroupID]
      ,M.[SourceProgramLongName]
      ,M.[SourceProgramShortName]
      ,M.[MajorComponentCharacteristic]
      ,M.[ProgramMilestone]
      ,M.[UsageID]
      ,M.[LaborSourceID]
      ,M.[Size]
      ,M.[LaborHours]
      ,M.[AverageLaborType]
      ,M.[MOQEquation]
      ,M.[MOQTypeID]
      ,M.[MOQText]
      ,M.[MetricStatusID]
      ,M.[MetricOwnerETIUserID]
      ,M.[MetricMinedETIUserID]
      ,M.[MetricMinedDate]
      ,M.[MetricValidatedETIUserID]
      ,M.[MetricValidatedDate]
      ,M.[MetricSupportingDataETIUserID]
      ,M.[MetricSupportingDataDate]
      ,M.[CustomerApprovalRequiredFlag]
      ,M.[DataSourceLocation]
      ,M.[MetricInUse]
      ,M.[UpdatedByETIUserID]
      ,M.[UpdateDT]
      ,@VersionID
      ,M.LaborHourMetric
  FROM [dbo].[Metric] M
INNER JOIN [dbo].[BOETaskElementMetricXREF] MX ON M.MetricID = MX.MetricID
INNER JOIN [dbo].[BOETaskElement] BTE ON MX.BOETaskElementID = BTE.BOETaskElementID
INNER JOIN dbo.BOE B ON BTE.BOEID  = B.BOEID
INNER JOIN dbo.Workspace WS ON B.WorkspaceID = WS.WorkspaceID
WHERE WS.WorkspaceID = @WorkspaceID

