CREATE PROCEDURE [dbo].[deleteAllWorkspaceResourceDTS]
(
@WorkspaceID int,
@WorkspaceRegionDTSID int
)
AS
/******************************************************************************
**		 
**		Name: [deleteAllWorkspaceResourceDTS]
**		Desc: Delete all parts of Workspace Resource DTS that are under 
**				the Workspace for that Region
**				NOTE: Since it is deleting All, no Update DT being checked
**						Need to confirm with developers
**		
**
**		Auth: Don Canuso
**		Date: 8/27/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			--------------------------------------
*****************************************************************************/
SET NOCOUNT ON 

DELETE FROM dbo.WorkspaceResourceDTS 
WHERE 
	WorkspaceID = @WorkspaceID AND
	WorkspaceRegionDTSID = @WorkspaceRegionDTSID

GO

