CREATE PROCEDURE [dbo].[deleteBOE]
(
@BOEID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteBOE]
**		Desc: Delete all parts of BOE
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19		dcanuso				RETURN was not working properly - corrected
**		9/13/10		dcanuso				Soft Deletes removed
**		9/14/10		dcanuso				Noticed the deletion ordering was 
**										incorrect - BOE should be last and 
**										XREF was missing
**		10/6/10		dcanuso				Variables were added and need to be handled 
**										on deletion
**		11/9/10		dcanuso				Removal of [WBS_CLIN_BOE_XREF] from database
**										Columns Added to BOE table
**		12/31/10	dillea				Jim added a delete from the BOE State History
**										table
**		3/8/11		dcanuso				WBS_CLIN_BOE_XREF is back and needs to be added
**		4/21/11		dcanuso				Added DELETE statements for additional
**										tables that have been added to DB
**		5/3/11		dcanuso				BOETaskElementMetricXREF added
**		5/19/11		dcanuso				Changed the order of deletes
**		7/20/11		dcanuso				Fixed the processing of In Use
**		7/21/11		dcanuso				Added additional tables
**		8/18/11		dcanuso				Cost Element Custom Field
**										Tables added 
**		8/31/11		dcanuso				Added OrdinaryVariableSumVariableResourceTypeXREF
**		9/19/11		dcanuso				WI 5160 BOE User Role History Table Added
**		9/20/11		dcanuso				WI 5272
**		10/31/11	dcanuso				Need the change before and after for WI5272
**		11/18/11	dcanuso				WI 6072:The DeleteTravelTripTaskElement SP
**										should check if the Trip's TripInUse flag can be reset. 
**		12/15/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		1/12/12		dcanuso				WI 6698 Metric In Use is not being handled
**		5/22/12		dcanuso				Columns removed during locking redesign
**		7/9/12		dcanuso				WI 9739
**										Description:
**										Able to delete a trip within the two year 
**										of the last time it's been used. 
**										According to the wireframe: Do not allow 
**										a trip to be deleted unless it has been 2 years 
**										after the "Last Used" date. Display "In Use" in 
**										place of the Delete checkbox 
**										for the trips that are in use until 2 years 
**										after the "Last Used" date.
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		1/14/13		dcanuso				WI 14397: Code will now call 
**										EXEC  [dbo].[updatePerformingOrganizationInUseFlagByWorkspaceID] @WorkspaceID
**										after the delete ends rather than after each delete
**		2/4/13		dcanuso				WI14842 Redesign Performing Organization
**		12/9/13		dcanuso				WI 24983 - OrdinaryVariable.Default Size
**										BOE Task Elemet genData Metric XREF
**		8/27/14		dcanuso				Image Story
**		10/3/14		dcanuso				Image Story Removal
**		7/30/15		dcanuso				Metric Details
*****************************************************************************/
SET NOCOUNT ON 

	IF (SELECT UpdateDT FROM [dbo].[BOE] WHERE BOEID = @BOEID) = @UpdateDT
		BEGIN
			SET @UpdateDT = GETDATE()
			
			DELETE FROM dbo.BOELaborSpread
			FROM dbo.BOELaborSpread LS
				INNER JOIN dbo.BOELaborType LT ON LS.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID

			DELETE FROM dbo.BOELaborTypeCustomFieldValueXREF
			FROM dbo.BOELaborTypeCustomFieldValueXREF X
				INNER JOIN dbo.BOELaborType LT ON X.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID
				
			/*WI 5272*/				
			DELETE FROM dbo.SumOfBOE_OrdinaryVariableXREF
			FROM dbo.SumOfBOE_OrdinaryVariableXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID
								
			DELETE FROM dbo.SumOfBOE_OrdinaryVariableXREF
			WHERE
				BOEID = @BOEID
				
			DELETE FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF
			FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID
				
			DELETE FROM dbo.OrdinaryVariable
			FROM dbo.OrdinaryVariable OV
				INNER JOIN dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID
				
			DELETE FROM dbo.BOECustomFieldValueXREF
			WHERE BOEID = @BOEID
			
			DELETE FROM dbo.BOELaborType
			FROM dbo.BOELaborType LT 
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID
				
			DELETE FROM dbo.BOEApprovalHistory
			WHERE BOEID = @BOEID
			
			DELETE FROM dbo.BOECommentHistory
			WHERE BOEID = @BOEID
				
			DELETE FROM dbo.BOETaskElementCustomFieldValueXREF
			FROM dbo.BOETaskElementCustomFieldValueXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID
		
			/*Table to check Metrics*/
			DECLARE @Metric TABLE (MetricID int)
			INSERT INTO @Metric 
			SELECT X.MetricID 
			FROM dbo.BOETaskElementMetricXREF  X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID	

			DELETE FROM dbo.BOETaskElementMetricXREF
				FROM dbo.BOETaskElementMetricXREF  X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID	

			DELETE FROM dbo.BOETaskElementgenDataMetricXREF
				FROM dbo.BOETaskElementgenDataMetricXREF  X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID					

			DELETE FROM [dbo].[BOETaskElementMetricDetailXREF]
				FROM [dbo].[BOETaskElementMetricDetailXREF] X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
			WHERE
				B.BOEID = @BOEID			
				
			/*
			Now that the BOETaskElementMetricXREF has been deleted
			
			Check if Metric is still In Use
			*/
			UPDATE [dbo].[Metric]
				SET [MetricInUse] =	
					CASE
						WHEN X.MetricID IS NULL THEN 0
						ELSE 1 /*In Use*/
					END
				FROM  [dbo].[Metric] M
				INNER JOIN @Metric tM ON M.MetricID = tM.MetricID /*Only Need to check the deleted list*/
