CREATE PROCEDURE [dbo].[deleteBOETaskElement]
(
@BOETaskElementID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteBOETaskElement]
**		Desc: Delete Flag set in LM Task Element Section of BOE and all sub-elements (Labor Types and Labor Spread)
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19/10		dcanuso				RETURN was not working properly - corrected
**		9/13/10		dcanuso				Soft deletes removed
**		10/6/10		dcanuso				Variables were added and need to be added
**		4/21/11		dcanuso				Added new tables that need DELETE statements
**		5/3/11		dcanuso				BOETaskElementMetricXREF added
**		7/20/11		dcanuso				Fixed the processing of In Use
**		8/18/11		dcanuso				Commented out extra In Use Processing
**										for BOE Custom Fields
**		8/31/11		dcansuo				Added OrdinaryVariableSumVariableResourceTypeXREF
**		12/15/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		2/4/13		dcanuso				WI14842 Redesign Performing Organization
**		12/9/13		dcanuso				WI 24983 - BOE Task Elemet genData Metric XREF
**		8/27/14		dcanuso				Image Story
**		10/3/14		dcanuso				Image Story Removal
**		7/30/15		dcanuso				metric detail
*******************************************************************************/
SET NOCOUNT ON 


	IF (SELECT UpdateDT FROM [dbo].[BOETaskElement] WHERE BOETaskElementID = @BOETaskElementID) = @UpdateDT
		BEGIN

			DELETE FROM dbo.BOELaborSpread
				FROM dbo.BOELaborSpread LS
				INNER JOIN dbo.BOELaborType LT ON LS.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
			WHERE
				TE.BOETaskElementID = @BOETaskElementID
				
			
			DELETE FROM dbo.BOELaborTypeCustomFieldValueXREF
			FROM dbo.BOELaborTypeCustomFieldValueXREF X
				INNER JOIN dbo.BOELaborType LT ON X.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
			WHERE
				TE.BOETaskElementID = @BOETaskElementID
				
				
			DELETE FROM dbo.BOETaskElementWorkspaceVariableXREF
			WHERE
				BOETaskElementID = @BOETaskElementID
				
			DELETE FROM dbo.SumOfBOE_OrdinaryVariableXREF
			FROM  dbo.SumOfBOE_OrdinaryVariableXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN  dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
			WHERE TE.BOETaskElementID = @BOETaskElementID
			

			DELETE FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF
			FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN  dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
			WHERE TE.BOETaskElementID = @BOETaskElementID

				

			DELETE FROM dbo.OrdinaryVariable
			FROM dbo.OrdinaryVariable OV
				INNER JOIN dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
			WHERE TE.BOETaskElementID = @BOETaskElementID
				
				
			DELETE FROM dbo.BOETaskElementCustomFieldValueXREF
			FROM dbo.BOETaskElementCustomFieldValueXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
			WHERE TE.BOETaskElementID = @BOETaskElementID
			
			
			/*Table to check Metrics*/
			DECLARE @Metric TABLE (MetricID int)
			INSERT INTO @Metric 
			SELECT X.MetricID 
			FROM dbo.BOETaskElementMetricXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
			WHERE TE.BOETaskElementID = @BOETaskElementID
			
			
			DELETE FROM dbo.BOETaskElementMetricXREF
				FROM dbo.BOETaskElementMetricXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
			WHERE TE.BOETaskElementID = @BOETaskElementID		
				

			DELETE FROM dbo.BOETaskElementgenDataMetricXREF
				FROM dbo.BOETaskElementgenDataMetricXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
			WHERE TE.BOETaskElementID = @BOETaskElementID		



			DELETE FROM [dbo].[BOETaskElementMetricDetailXREF]
				FROM [dbo].[BOETaskElementMetricDetailXREF] X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
			WHERE TE.BOETaskElementID = @BOETaskElementID	

			/*
			Now that the BOETaskElementMetricXREF has been deleted
			
			Check if Metric is still In Use
			*/
			UPDATE [dbo].[Metric]
				SET [MetricInUse] =	
					CASE
						WHEN X.MetricID IS NULL THEN 0
						ELSE 1 /*In Use*/
					END
				FROM  [dbo].[Metric] M
				INNER JOIN @Metric tM ON M.MetricID = tM.MetricID /*Only Need to check the deleted list*/
					LEFT OUTER JOIN dbo.BOETaskElementMetricXREF X ON M.MetricID = X.MetricID

			
	
			
 
			DELETE FROM dbo.BOELaborType
				FROM dbo.BOELaborType LT
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
			WHERE
				TE.BOETaskElementID = @BOETaskElementID
				
				
			DECLARE @WorkspaceID int
			SELECT @WorkspaceID = WorkspaceID 
			FROM dbo.BOE B
				INNER JOIN dbo.BOETaskElement TE ON B.BOEID = TE.BOEID
			WHERE TE.BOETaskElementID = @BOETaskElementID

			
			DELETE FROM dbo.BOETaskElement
			WHERE
				BOETaskElementID = @BOETaskElementID
				
/*
Fix All In Use Flags
*/
/*Check if Resource is used elsewhere*/
/*EXECUTE [dbo].[updateResourceInUseFlagByWorkspaceID] @WorkspaceID*/



/*Check if PerformingOrganization is used elsewhere*/
/*EXECUTE [dbo].[updatePerformingOrganizationInUseFlagByWorkspaceID] @WorkspaceID*/
		
/*
Not needed as we are not deleting or changing data in BOECustomFieldValueXREF

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = CASE 
										WHEN X.[CustomFieldValueID] IS NULL THEN 0
										WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
									END,
		UpdateDT = GETDATE()
FROM dbo.CustomFieldValue CFV 
	INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
	LEFT OUTER JOIN [dbo].[BOECustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CF.WorkspaceID = @WorkspaceID
*/

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = CASE 
										WHEN X.[CustomFieldValueID] IS NULL THEN 0
										WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
									END,
		UpdateDT = GETDATE()
FROM dbo.CustomFieldValue CFV 
	INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
	LEFT OUTER JOIN [dbo].[BOELaborTypeCustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CF.WorkspaceID = @WorkspaceID

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = CASE 
										WHEN X.[CustomFieldValueID] IS NULL THEN 0
										WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
									END,
		UpdateDT = GETDATE()
FROM dbo.CustomFieldValue CFV 
	INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
	LEFT OUTER JOIN [dbo].[BOETaskElementCustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CF.WorkspaceID = @WorkspaceID				

		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in BOETaskElement with BOETaskElementID ' + CAST(@BOETaskElementID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
 
		END

GO

