CREATE PROCEDURE [dbo].[deleteBOETaskElementMetric]
(
@BTEMID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteBOETaskElementMetric]
**		Desc: Delete the association between BOE Task Element and Metric
**			
**		
**
**		Auth: Don Canuso
**		Date: 5/5/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
*******************************************************************************/
SET NOCOUNT ON 


	IF (SELECT UpdateDT FROM dbo.BOETaskElementMetricXREF WHERE BTEMID = @BTEMID ) = @UpdateDT
		BEGIN
		
			DECLARE @DeletedMetricID int
			SELECT @DeletedMetricID = MetricID FROM dbo.BOETaskElementMetricXREF WHERE BTEMID = @BTEMID


			DELETE FROM dbo.BOETaskElementMetricXREF WHERE BTEMID = @BTEMID
		
					
			/*Check if Metric is still In Use*/
			UPDATE [dbo].[Metric]
				SET [MetricInUse] =	
					CASE
						WHEN X.MetricID IS NULL THEN 0
						ELSE 1 /*In Use*/
					END
				FROM  [dbo].[Metric] M
					LEFT OUTER JOIN dbo.BOETaskElementMetricXREF X ON M.MetricID = X.MetricID
				WHERE M.MetricID = @DeletedMetricID
			
		END
	ELSE
