CREATE PROCEDURE [dbo].[deleteCustomFieldValueByCustomFieldID]
(
@CustomFieldID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteCustomFieldValueByCustomFieldID]
**		Desc: Delete Custom Field Values Based On CustomFieldID
**				Will delete all values not in use
**				Update Date is from Custom Field
**
**		Auth: Don Canuso
**		Date: 2/2/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
******************************************************************************/
SET NOCOUNT ON 


	IF (SELECT UpdateDT FROM [dbo].[CustomField] WHERE CustomFieldID = @CustomFieldID) = @UpdateDT
		BEGIN
			DELETE FROM [dbo].[CustomFieldValue] WHERE CustomFieldID = @CustomFieldID AND CustomFieldValueInUseFlag = 0
		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
