				INNER JOIN dbo.BOE B ON TE.BOEID = B.BOEID
				INNER JOIN @MockWorkspace WS ON B.WorkspaceID = WS.WorkspaceID




			DELETE FROM dbo.BOELaborTypeCustomFieldValueXREF
