CREATE PROCEDURE [dbo].[deleteHistoricalMetric]
(
@MetricID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: deleteHistoricalMetric
**		Desc: Deletes a Metric
**			
**		   
**		
**
**		Auth: Don Canuso
**		Date: 4/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		5/5/11		dcanuso				Metric moved from BOE Task Elemement
*******************************************************************************/
SET NOCOUNT ON 
DECLARE @ErrorMessage varchar (500)

IF (SELECT UpdateDT FROM dbo.Metric WHERE MetricID = @MetricID) = @UpdateDT
	BEGIN
			
		IF EXISTS (SELECT 1 FROM dbo.BOETaskElementMetricXREF WHERE MetricID = @MetricID)
			BEGIN
				/*
					Metric is in use
				*/
					SET @ErrorMessage =   'The MetricID ' + CAST (@MetricID AS varchar(10)) + ' is in use within a BOE Task Element.'
					RAISERROR (
						@ErrorMessage, -- Message text.
						11, -- Severity,/*Severity Changed to 11*/
						1 -- State,
						)
					RETURN
			END
		ELSE
			BEGIN

				DELETE FROM dbo.Metric WHERE MetricID = @MetricID 
			
			END
		
	END
ELSE
	BEGIN
		
		SET @ErrorMessage =   'The row in Metric with MetricID ' + CAST(@MetricID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
		
		RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
	END

GO

