CREATE PROCEDURE [dbo].[deleteLaborResourceRate]
(
@LaborResourceRateID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteLaborResourceRate]
**		Desc: Delete the specified Labor Resource Rate if not in use
**			
**		
**
**		Auth: Don Canuso
**		Date: 11/29/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			--------------------------------------
**		1/17/12		dcanuso				Need to check Locked Table
**		2/6/12		dcanuso				More changes to InUse Processing
**		1/17/13		DCANUSO				WI 14477
**										If Labor Resource Rate is deleted for a 
**										given date range, any unique resources 
**										with resourcelistid=1 that match this rate 
**										would have their rate also deleted
******************************************************************************/
SET NOCOUNT ON 


IF (SELECT UpdateDT FROM dbo.LaborResourceRate WHERE LaborResourceRateID = @LaborResourceRateID) = @UpdateDT
	BEGIN
	

		DECLARE @InUseFlag int,
				@ResourceID int
		SELECT @ResourceID = SystemResourceID 
		FROM dbo.LaborResourceRate 
		WHERE  LaborResourceRateID = @LaborResourceRateID

		DECLARE @temp TABLE (ReturnValue int NOT NULL)

		INSERT @temp EXECUTE [dbo].[getResourceInUseFlagBySystemResourceID] @ResourceID

		SELECT @InUseFlag = ReturnValue FROM @temp

		IF @InUseFlag = 0
		BEGIN
		
		/*WI 14477*/
		DELETE FROM dbo.LaborResourceRate
		FROM dbo.LaborResourceRate D 
		INNER JOIN 
		(
			SELECT M.LaborResourceRateID
			FROM [dbo].[LaborResourceRate] LRR
			INNER JOIN [dbo].[Resource] R ON LRR.SystemResourceID = R.ResourceID
			INNER JOIN
				(
				SELECT  
					MLRR.LaborResourceRateEndDate, 
					MLRR.LaborResourceRateID, 
					MLRR.LaborResourceRateStartDate, 
					MLRR.ResourceRate,
					MR.CostElementID,
					MR.LaborType,
					MR.ResourceID,
					MR.ResourceName,
					MR.SegmentID,
					MR.SegmentRegion
				FROM [dbo].[LaborResourceRate] MLRR 
					INNER JOIN [dbo].[Resource] MR ON MLRR.SystemResourceID = MR.ResourceID
				WHERE MR.ResourceListID = 1
				) M		
			ON	
				LRR.LaborResourceRateStartDate = M.LaborResourceRateStartDate AND
				LRR.LaborResourceRateEndDate = M.LaborResourceRateEndDate AND
				/*Matching Resource By Name*/	 
				R.ResourceName = M.ResourceName AND
				R.SegmentRegion = M.SegmentRegion AND
				R.LaborType = M.LaborType AND
				R.SegmentID = M.SegmentID AND
				R.CostElementID = M.CostElementID AND
				R.ResourceID <> M.ResourceID
			WHERE
				LRR.LaborResourceRateID = @LaborResourceRateID 
		) DM ON D.LaborResourceRateID  = DM.LaborResourceRateID
		
		
		DELETE FROM dbo.LaborResourceRate
		FROM dbo.LaborResourceRate LRR
			INNER JOIN [dbo].[Resource] R ON LRR.SystemResourceID = R.ResourceID
			/*Locked Rates do not affect LRR - They can still be deleted
			LEFT OUTER JOIN dbo.WorkspaceLockedLaborResourceRate L ON R.ResourceID = L.SystemResourceID
			*/
			LEFT OUTER JOIN dbo.WorkspaceResourceRate WRR ON R.ResourceID = WRR.SystemResourceID
		WHERE
			LRR.LaborResourceRateID = @LaborResourceRateID AND
			/*L.SystemResourceID IS NULL AND */
			WRR.SystemResourceID IS NULL /*AND*/
			/*NO WORKSPACE (Locked and Not-Locked) IS USING IT*/
			/*No longer storing In Use for LRR in DB
			LRR.LaborResourceRateInUseFlag = 0*/
			
			
		


		
		END
	END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in LaborResourceRate with LaborResourceRateID ' + CAST(@LaborResourceRateID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN

		END

GO

