CREATE PROCEDURE [dbo].[deleteMaterial]
(
@MaterialID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteMaterial]
**		Desc: Delete Material in Material Section
**			
**		
**
**		Auth: Don Canuso
**		Date: 6/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		7/6/11		DCANUSO				Material.ResourceID added
**		8/18/11		dcanuso				Adding Custom Field Tables
**		11/25/11	dcanuso				InUse Processing updated
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
*******************************************************************************/
SET NOCOUNT ON 


	IF (SELECT UpdateDT FROM [dbo].[Material] WHERE MaterialID = @MaterialID ) = @UpdateDT
		BEGIN
		
			DELETE FROM dbo.MaterialSpread
			WHERE
				MaterialID = @MaterialID
	
			/*Variables Used for InUse Function*/
/*			DECLARE		@CurrentResourceID int
			
			SELECT	@CurrentResourceID  = ResourceID
			FROM [dbo].[Material]
			WHERE MaterialID = @MaterialID
*/
			DELETE FROM dbo.MaterialCustomFieldValueXREF
			FROM dbo.MaterialCustomFieldValueXREF X
				INNER JOIN dbo.Material M ON X.MaterialID = M.MaterialID
			WHERE M.MaterialID = @MaterialID


			DELETE FROM dbo.Material
			WHERE
				MaterialID = @MaterialID
	
			/*Update In Use Flag*/
/*			EXECUTE [dbo].[updateResourceInUseFlagByResourceID] @CurrentResourceID*/


				/*Used to Handle In Use Processing*/
				DECLARE @WorkspaceID int
				SELECT @WorkspaceID = WorkspaceID 
				FROM dbo.BOE B
					INNER JOIN dbo.MaterialTaskElement TE ON B.BOEID = TE.BOEID
					INNER JOIN dbo.Material M ON TE.MaterialTaskElementID = M.MaterialTaskElementID
				WHERE M.MaterialID = @MaterialID
	
	
				UPDATE dbo.CustomFieldValue
				SET CustomFieldValueInUseFlag = CASE 
													WHEN X.[CustomFieldValueID] IS NULL THEN 0
													WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
												END,
					UpdateDT = GETDATE()
				FROM dbo.CustomFieldValue CFV 
					INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
					LEFT OUTER JOIN [dbo].[MaterialCustomFieldValueXREF] X ON
						CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
				WHERE 
					CF.WorkspaceID = @WorkspaceID

	
		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in Material with MaterialID ' + CAST(@MaterialID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN

		END

GO

