CREATE PROCEDURE [dbo].[deleteMaterialTaskElement]
(
@MaterialTaskElementID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteMaterialTaskElement]
**		Desc: Delete Material Task Element in Material Section of BOE and all sub-elements
**			
**		
**
**		Auth: Don Canuso
**		Date: 6/22/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		8/18/11		dcanuso				Adding Custom Field Tables
**		12/15/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		8/27/14		dcanuso				Image Story
**		10/3/14		dcanuso				Image Story Removal
*******************************************************************************/
SET NOCOUNT ON 


	IF (SELECT UpdateDT FROM [dbo].[MaterialTaskElement] WHERE MaterialTaskElementID = @MaterialTaskElementID) = @UpdateDT
		BEGIN

			DELETE FROM dbo.MaterialSpread
				FROM dbo.MaterialSpread S
				INNER JOIN dbo.Material M ON S.MaterialID = M.MaterialID
				INNER JOIN dbo.MaterialTaskElement TE ON M.MaterialTaskElementID = TE.MaterialTaskElementID
			WHERE
				TE.MaterialTaskElementID = @MaterialTaskElementID

			DELETE FROM dbo.MaterialCustomFieldValueXREF
				FROM dbo.MaterialCustomFieldValueXREF X
				INNER JOIN dbo.Material M ON X.MaterialID = M.MaterialID
				INNER JOIN dbo.MaterialTaskElement TE ON M.MaterialTaskElementID = TE.MaterialTaskElementID
			WHERE
				TE.MaterialTaskElementID = @MaterialTaskElementID
			
			DELETE FROM dbo.Material
				FROM dbo.Material M
				INNER JOIN dbo.MaterialTaskElement TE ON M.MaterialTaskElementID = TE.MaterialTaskElementID
			WHERE
				TE.MaterialTaskElementID = @MaterialTaskElementID
				
			DELETE FROM dbo.MaterialTaskElementCustomFieldValueXREF				
				FROM dbo.MaterialTaskElementCustomFieldValueXREF X
				INNER JOIN dbo.MaterialTaskElement TE ON X.MaterialTaskElementID = TE.MaterialTaskElementID
			WHERE
				TE.MaterialTaskElementID = @MaterialTaskElementID


			/*Used to Handle In Use Processing*/
			DECLARE @WorkspaceID int
			SELECT @WorkspaceID = WorkspaceID 
			FROM dbo.BOE B
				INNER JOIN dbo.MaterialTaskElement TE ON B.BOEID = TE.BOEID
			WHERE TE.MaterialTaskElementID = @MaterialTaskElementID


			DELETE FROM dbo.MaterialTaskElement
			WHERE
				MaterialTaskElementID = @MaterialTaskElementID	

			/*Handle In Use Processing*/
/*			EXECUTE [dbo].[updateResourceInUseFlagByWorkspaceID] @WorkspaceID*/

			UPDATE dbo.CustomFieldValue
				SET CustomFieldValueInUseFlag = CASE 
													WHEN X.[CustomFieldValueID] IS NULL THEN 0
													WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
												END,
					UpdateDT = GETDATE()
			FROM dbo.CustomFieldValue CFV 
				INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
				LEFT OUTER JOIN [dbo].[MaterialCustomFieldValueXREF] X ON
					CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
			WHERE 
				CF.WorkspaceID = @WorkspaceID

			UPDATE dbo.CustomFieldValue
				SET CustomFieldValueInUseFlag = CASE 
													WHEN X.[CustomFieldValueID] IS NULL THEN 0
													WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
												END,
					UpdateDT = GETDATE()
			FROM dbo.CustomFieldValue CFV 
				INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
				LEFT OUTER JOIN [dbo].[MaterialTaskElementCustomFieldValueXREF] X ON
					CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
			WHERE 
				CF.WorkspaceID = @WorkspaceID


				
		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in MaterialTaskElement with MaterialTaskElementID ' + CAST(@MaterialTaskElementID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
 
		END

GO

