CREATE PROCEDURE [dbo].[deleteODCTaskElementCustomFieldValue]
(
@OTECFVID [int],
@ODCTaskElementID [int],
@CustomFieldValueID [int],
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteODCTaskElementCustomFieldValue]
**		Desc: Deletes data from the dbo.ODCTaskElementCustomFieldValueXREF table which
**				holds the Custom Field Value for the ODC Task Element
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/17/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		12/14/11	dcanuso				WI 6166
*******************************************************************************/
SET NOCOUNT ON 

IF (SELECT UpdateDT FROM [dbo].[ODCTaskElementCustomFieldValueXREF] WHERE OTECFVID = @OTECFVID) = @UpdateDT
	BEGIN
		DELETE FROM [dbo].[ODCTaskElementCustomFieldValueXREF] WHERE OTECFVID = @OTECFVID
		
		/*Only should be looking within the scope
		of the Custom Field, so if the scope is ODCType
		then only look in ODCTypeCustomFieldValueXREF
		*/
				
		IF NOT EXISTS (SELECT [CustomFieldValueID] FROM [dbo].[ODCTaskElementCustomFieldValueXREF]
						WHERE CustomFieldValueID = @CustomFieldValueID)
			BEGIN
				
				UPDATE dbo.CustomFieldValue
				SET CustomFieldValueInUseFlag = 0,
					UpdateDT = GETDATE()
				FROM dbo.CustomFieldValue CFV 
				WHERE CFV.CustomFieldValueID = @CustomFieldValueID
				
			END


	END
ELSE
	BEGIN
		DECLARE @ErrorMessage varchar (500)
			SET @ErrorMessage =  'The row in ODCTaskElementCustomFieldValueXREF with OTECFVID ' + CAST(@OTECFVID AS varchar(10)) +  ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
		RAISERROR (
				@ErrorMessage, -- Message text.
		        11, -- Severity,/*Severity Changed to 11*/
				1 -- State,
				)
		RETURN
	END


GO

