CREATE PROCEDURE [dbo].[deleteOutputFormatTemplate]
(
@TemplateID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteOutputFormatTemplate]
**		Desc: Delete the Output Format Template if no one is using it
**			
**		
**
**		Auth: Don Canuso
**		Date: 3/30/2011
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		9/6/13		dcanuso				Allowing the deleting of Templates 
**										even if used by System Admins.
*******************************************************************************/
SET NOCOUNT ON 
DECLARE @ErrorMessage varchar (500)

IF (SELECT UpdateDT FROM [dbo].[OutputFormatTemplate] WHERE TemplateID = @TemplateID) = @UpdateDT
		BEGIN
		
		/*In use determined by code*/
/*			IF EXISTS (SELECT 1 FROM dbo.OutputFormatTemplateWorkspaceXREF WHERE TemplateID = @TemplateID)
				BEGIN
					SET @ErrorMessage =   'The TemplateID ' + CAST(@TemplateID AS varchar(10)) + ' is in use.'
					RAISERROR	(
								@ErrorMessage, -- Message text.
								11, -- Severity,/*Severity Changed to 11*/
								1 -- State,
								)
					RETURN
				END
*/
						
				UPDATE dbo.OutputFormatTemplate
				SET IsActive = 0
				WHERE  TemplateID = @TemplateID 
		END
	ELSE
		BEGIN
				SET @ErrorMessage =   'The row in OutputFormatTemplate with ID ' + CAST(@TemplateID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
						@ErrorMessage, -- Message text.
						11, -- Severity,/*Severity Changed to 11*/
						1 -- State,
						)
				RETURN
		END

IF @@ERROR = 0
	SELECT	@TemplateID AS TemplateID

GO

