CREATE PROCEDURE [dbo].[deleteWorkspaceResourceRate]
(
@WorkspaceResourceRateID int,
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: [deleteWorkspaceResourceRate]
**		Desc: Delete the specified Workspace Resource Rate if not in use
**				Per SE: Can not delete a Workspace Resource Rate associated with
**				an in use Resource
**
**		Auth: Don Canuso
**		Date: 11/29/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			--------------------------------------
**		1/11/12		dcanuso				WI 6579:
**										The Resource Selected/Mapped in the
**										WorkspaceResourceRate Table does not
**										 affect In Use Flag per SEs
**		1/17/12		dcanuso				New table for Locking Rates
**		2/6/12		dcanuso				More updates to the way InUse is handled
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
******************************************************************************/
SET NOCOUNT ON 


IF (SELECT UpdateDT FROM dbo.WorkspaceResourceRate WHERE WorkspaceResourceRateID = @WorkspaceResourceRateID) = @UpdateDT
	BEGIN
	
		/* 
		After we delete the WRR
		we need to check if anything
		else is using the LRR
		*/
		/*
		DECLARE	@SystemResourceID int
		SELECT	@SystemResourceID = SystemResourceID,
				@UpdateDT = GetDate() /*Get The Date*/
		FROM dbo.WorkspaceResourceRate
		WHERE	WorkspaceResourceRateID = @WorkspaceResourceRateID AND
				SystemResourceID IS NOT NULL
		*/

		DELETE FROM dbo.WorkspaceResourceRate
		WHERE WorkspaceResourceRateID = @WorkspaceResourceRateID
		/*
		IF @SystemResourceID IS NOT NULL
			EXECUTE [dbo].[updateResourceInUseFlagByResourceID] @SystemResourceID
		*/

		/*
		Need to check if the System Resource 
		is being used anywhere else,
		If yes, leave it alone (should be set to In Use Already)
		If no, set flag to false - not in use
		
		If it is being used, the nothing should have to change
		*/
		/*Only checking if this is the last WRR using the System Resource*/

		/*	
		IF NOT EXISTS	(
							SELECT SystemResourceID 
							FROM dbo.WorkspaceResourceRate
							WHERE SystemResourceID = @SystemResourceID 
						)
		BEGIN
			/* 
				The deleted WRR was the last one using
				LRR and LRR Flag needs to be reset 
				and Resource used needs to be rechecked
			*/
			/*
			Labor Resource Rate is tied with 
			Resource (System/Global/ISGSDefault) 
			so Labor Resource Rate In Use 
			will be processed at the same time as 
			Resource (System/Global/ISGSDefault) 


			UPDATE dbo.LaborResourceRate
			SET LaborResourceRateInUseFlag = 0
			WHERE SystemResourceID = @SystemResourceID 
			*/			
			EXECUTE [dbo].[updateResourceInUseFlagByResourceID] @SystemResourceID

		END*/
END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in WorkspaceResourceRate with WorkspaceResourceRateID ' + CAST(@WorkspaceResourceRateID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN

		END

GO

