CREATE PROCEDURE [dbo].[FinancialLeadershipAcademy_getQuotingMethodCount]
(
	@WorkspaceID int
)
AS
/******************************************************************************
**		 
**		Name: FinancialLeadershipAcademy_getQuotingMethodCount
**		Desc: 
**			
**		
**
**		Auth: Don Canuso
**		Date: 5/26/14
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
*******************************************************************************/
SET NOCOUNT ON 

--For these BOEs……..Task by Method of Quoting 
SELECT A.WorkspaceName, A.MOQType, SUM (A.QuoteMethodCount) AS QuoteMethodCount
FROM
(
SELECT 
/*	COUNT(*) AS NumberOfLaborBOEs,*/
	W.WorkspaceName,
/*	B.BOEID,*/
/*	Hrs.TotalLaborSpreadValue,*/
	MOQType.MOQType,
	MOQType.QuoteMethodCount
FROM dbo.BOE B
	INNER JOIN dbo.Workspace W ON B.WorkspaceID = W.WorkspaceID
	INNER JOIN 
		(
			SELECT SUM (LS.LaborSpreadValue) AS TotalLaborSpreadValue, TE.BOEID
			FROM dbo.BOETaskElement TE 
				INNER JOIN dbo.BOELaborType LT ON TE.BOETaskElementID = LT.BOETaskElementID
				INNER JOIN dbo.BOELaborSpread LS ON LT.BOELaborTypeID = LS.BOELaborTypeID
			WHERE 
				TE.TaskElementTypeID = 1 /*LABOR*/ AND
				LT.[SpreadTypeID] = 1 /*hours*/ 								
			GROUP BY TE.BOEID
			HAVING SUM (LS.LaborSpreadValue) > 1000
		) Hrs  ON B.BOEID = Hrs.BOEID
	INNER JOIN 
		(
			SELECT /*TE.BOETaskElementID,*/ TE.BOEID, M.MOQType, COUNT(*) AS QuoteMethodCount
			FROM dbo.BOETaskElement TE 
				INNER JOIN dbo.MOQTypeLU M ON TE.MOQTypeID = M.MOQTypeID				
			WHERE 
				TE.TaskElementTypeID = 1 /*LABOR*/ 
			GROUP BY TE.BOEID, M.MOQType
		) MOQType  ON B.BOEID = MOQType.BOEID
	INNER JOIN
		(
			/*
				Workspace Create Date
				Only want reports from 1st Quarter 2014
			*/
			SELECT W.WorkspaceID, H.UpdateDT AS CreateDate 
			FROM dbo.Workspace W 
				INNER JOIN dbo.WorkspaceStateHistory H ON W.WorkspaceID = H.WorkspaceID
				INNER JOIN dbo.WorkspaceStateLU S ON H.CurrentWorkspaceStateID	 = S.WorkspaceStateID
			WHERE 
				H.CurrentWorkspaceStateID = 0 AND
				H.UpdatedWorkspaceStateID = 1 AND
H.UpdateDT >=  '01-01-2014' AND
H.UpdateDT <  '04-01-2014' 
		) WorkspaceCreateDate ON W.WorkspaceID = WorkspaceCreateDate.WorkspaceID		
WHERE 
	W.WorkspaceStateID = 4/*	Complete*/   AND
	(
		@WorkspaceID = -1 OR
		@WorkspaceID  IS NULL OR
		W.WorkspaceID = @WorkspaceID
	)
/*GROUP BY W.WorkspaceName, MOQType.MOQType, MOQType.QuoteMethodCount*/
) A
GROUP BY A.WorkspaceName, A.MOQType
ORDER BY A.WorkspaceName, A.MOQType

GO

