CREATE PROCEDURE [dbo].[generationMaintenance]
/******************************************************************************
**		 
**		Name: [generationMaintenance]
**		Desc: Index Plan For generation applications
**			
**
**		Auth: Don Canuso
**		Date: 3/6/2012
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			--------------------------------------
**		4/16/12		dcanuso				version schema should not be processed
**										Remove Any Indexes with NULL as Name
**										as they will not be processed
**		10/10/12	dcanuso				Adding schema to Missing Index and DROP
******************************************************************************/
AS

SET NOCOUNT ON

DECLARE
	@CurrentDate datetime2 = GetDate(),
	@CurrentIndex varchar(300),
	@CurrentFillFactor tinyint,
	@CurrentTableName varchar(300),
	@CurrentFragmentation float,
	@SQL VARCHAR(MAX)

INSERT INTO [dbo].[IndexFragmentation]
           ([TableName]
           ,[IndexName]
           ,[Fragmentation]
           ,[PageCount]
           ,[ObjectID]
           ,[IndexType]
           ,[FillFactor]
           ,[RecordCount]
           ,[DateProcessed]
           ,[Processed])

SELECT 
    OBJECT_SCHEMA_NAME(FRAG.[object_id]) + '.' + OBJECT_NAME(FRAG.[object_id]) AS [TableName],
    SIX.[name] AS IndexName,
    FRAG.avg_fragmentation_in_percent AS Fragmentation,
    FRAG.page_count AS [PageCount],
    SIX.[object_id] as ObjectID,
    FRAG.index_type_desc AS IndexType,
    SIX.fill_factor AS [FillFactor],
    FRAG.record_count AS [RecordCount],
    @CurrentDate AS DateProcessed,
    0 /*Processed = False*/
FROM
    sys.dm_db_index_physical_stats
    (
        DB_ID(),    --use the currently connected database
        0,          --Parameter for object_id.
        DEFAULT,    --Parameter for index_id.
        0,          --Parameter for partition_number.
        'DETAILED'     --Scanning mode. Default to "LIMITED", which is good enough
    ) FRAG
    INNER JOIN
    sys.indexes SIX ON	FRAG.[object_id] = SIX.[object_id] AND 
						FRAG.index_id = SIX.index_id
WHERE	FRAG.avg_fragmentation_in_percent > 0 AND
/*		OBJECT_SCHEMA_NAME(FRAG.[object_id]) = 'dbo' AND */
		SIX.[name] IS NOT NULL

UPDATE [dbo].[IndexFragmentation]
SET 
	[FillFactor] = 100 
WHERE 
	Processed = 0 AND
	IndexName LIKE 'PK%' AND
	[FillFactor] <>  100
	
	
UPDATE [dbo].[IndexFragmentation]
SET 
	[FillFactor] = 80
WHERE 
	Processed = 0 AND
	(
		(IndexName LIKE 'IX_%' AND 	[FillFactor] <>  80) OR
		(IndexName LIKE 'UK_%' AND 	[FillFactor] <>  80) 
	)

UPDATE [dbo].[IndexFragmentation]
SET 
	[FillFactor] = 80
WHERE 
	Processed = 0 AND
	[FillFactor] = 0




DELETE FROM [dbo].[IndexFragmentation] 
	WHERE IndexName IS NULL
 
WHILE EXISTS (SELECT 1 FROM [dbo].[IndexFragmentation] WHERE Processed = 0)
BEGIN
SELECT TOP 1 
	@CurrentIndex = IndexName,
	@CurrentFillFactor = [FillFactor],
	@CurrentTableName = TableName,
	@CurrentFragmentation = Fragmentation
FROM [dbo].[IndexFragmentation] WHERE Processed = 0

/*DBCC DBREINDEX (@CurrentTableName, @CurrentIndex, @CurrentFillFactor)*/
IF @CurrentFragmentation < 30
	BEGIN
		SET @SQL = 
			'ALTER INDEX ' + 
			'[' +  
			@CurrentIndex + 
			']' + 
			' ON ' + 
			@CurrentTableName + 
			' REORGANIZE'
	END


IF @CurrentFragmentation >= 30
	BEGIN
		SET @SQL = 
		'ALTER INDEX ' + 
		'[' +  
		@CurrentIndex + 
		']' + 
		' ON ' + 
		@CurrentTableName + 
		' REBUILD WITH (ONLINE = OFF, FILLFACTOR = ' + 
		CAST (@CurrentFillFactor AS varchar(3)) +
		', PAD_INDEX  = ON) '
	END

IF @SQL IS NOT NULL
	EXEC (@SQL)



SET @SQL = NULL

UPDATE [dbo].[IndexFragmentation]
SET Processed = 1
WHERE	
	@CurrentIndex = IndexName AND
	@CurrentFillFactor = [FillFactor] AND
	@CurrentTableName = TableName 

END



INSERT INTO  [dbo].[MissingIndex]
SELECT  
/*sys.objects.name AS TableName
*/
OBJECT_SCHEMA_NAME(O.[object_id]) + '.' + OBJECT_NAME(O.[object_id]) AS [TableName]
, (avg_total_user_cost * avg_user_impact) * (user_seeks + user_scans) AS Impact
,  'CREATE NONCLUSTERED INDEX ix_IndexName ON ' 
/*+ O.name
*/
 + OBJECT_SCHEMA_NAME(O.[object_id]) + '.' + OBJECT_NAME(O.[object_id])
 COLLATE DATABASE_DEFAULT + ' ( ' + IsNull(mid.equality_columns, '') + CASE WHEN mid.inequality_columns IS NULL 
                THEN ''  
    ELSE CASE WHEN mid.equality_columns IS NULL 
                    THEN ''  
        ELSE ',' END + mid.inequality_columns END + ' ) ' + CASE WHEN mid.included_columns IS NULL 
                THEN ''  
    ELSE 'INCLUDE (' + mid.included_columns + ')' END + ';' AS CreateIndexStatement
, mid.equality_columns AS EqualityColumns
, mid.inequality_columns AS InequalityColumns
, mid.included_columns AS IncludedColumns,
GetDate()  AS DateProcessed
    FROM sys.dm_db_missing_index_group_stats AS migs 
            INNER JOIN sys.dm_db_missing_index_groups AS mig ON migs.group_handle = mig.index_group_handle 
            INNER JOIN sys.dm_db_missing_index_details AS mid ON mig.index_handle = mid.index_handle AND mid.database_id = DB_ID() 
            INNER JOIN sys.objects O WITH (nolock) ON mid.OBJECT_ID = O.OBJECT_ID 
    WHERE     (migs.group_handle IN 
        ( 
        SELECT     TOP (500) group_handle 
            FROM          sys.dm_db_missing_index_group_stats WITH (nolock) 
            ORDER BY (avg_total_user_cost * avg_user_impact) * (user_seeks + user_scans) DESC))  
        AND OBJECTPROPERTY(O.OBJECT_ID, 'isusertable')=1 
    ORDER BY 2 DESC , 3 DESC 


INSERT INTO  [dbo].[MissingIndex]
           ([TableName]
           ,[CreateIndexStatement]
           ,[DateProcessed])
SELECT
	DropIndex.TableName,
	DropIndex.DropStatement,
	GetDate()  AS DateProcessed
FROM
	(	
	SELECT 
	o.name AS TableName, indexname=i.name, i.index_id   ,
	 reads=user_seeks + user_scans + user_lookups   ,
	  writes =  user_updates   , 
	  rows = (SELECT SUM(p.rows)
	   FROM sys.partitions p 
	   WHERE p.index_id = s.index_id AND s.object_id = p.object_id), 
	   CASE	WHEN s.user_updates < 1 THEN 100	ELSE 1.00 * (s.user_seeks + s.user_scans + s.user_lookups) / s.user_updates  END AS reads_per_write,
		'DROP INDEX ' + QUOTENAME(i.name) + ' ON ' + QUOTENAME(c.name) + '.' + QUOTENAME(OBJECT_NAME(s.object_id)) as 'dropstatement'
		FROM sys.dm_db_index_usage_stats s  
		INNER JOIN sys.indexes i ON i.index_id = s.index_id AND s.object_id = i.object_id   
		INNER JOIN sys.objects o on s.object_id = o.object_id
		INNER JOIN sys.schemas c on o.schema_id = c.schema_id
		WHERE OBJECTPROPERTY(s.object_id,'IsUserTable') = 1
		AND s.database_id = DB_ID()   
		AND i.type_desc = 'nonclustered'
		AND i.is_primary_key = 0
		AND i.is_unique_constraint = 0
		AND (SELECT SUM(p.rows)
		 FROM sys.partitions p 
		 WHERE p.index_id = s.index_id AND s.object_id = p.object_id) > 10000
		 /*ORDER BY reads*/
	) DropIndex 

EXEC sp_updatestats

GO

