CREATE PROCEDURE [dbo].[getBOEByWorkspaceID]
(
@WorkspaceID int
)
AS
/******************************************************************************
**		 
**		Name: [getBOEByWorkspaceID]
**		Desc: Returns the data for Manage BOEs by WorkspaceID
**			
**		
**
**		Auth: Don Canuso
**		Date: August 2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19/10		dcanuso				Added DELETED = 0 in WHERE for ETI User table, 
**										Added comma separated approver list, added clin dates
**		9/13/10		dcanuso				Soft Deletes removed - thus WHERE Deleted = is removed
**		9/29/10		dcanuso				Need to add key from XREF Table to be used in upsertBOE
**		11/1/10		dcanuso				Developer Request: Add Contract Start and End Date
**		11/9/10		dcanuso				Removal of [WBS_CLIN_BOE_XREF] from database
**										Columns Added to BOE table
**		3/1/11		dcanuso				INNER JOINs changed
**										NOTE:
**										BOE can now be created without CLINS
**										BOE Can be created with WBS, CLIN or WBS AND CLIN
**		3/7/11		dcanuso				WBS_CLIN_BOE_XREF returns and WBS/CLIN removed from BOE
******************************************************************************/
SET NOCOUNT ON 

/*Variables Needed for Stored Procedure*/
DECLARE		@ApprovalList VARCHAR(500), 
			@ApproverID int,
			@AuthorID int,
			@BOEID int

/*Calculate the Approvers*/
SELECT @ApproverID = RoleID FROM dbo.RoleLU WHERE RoleName = 'Approver'
SELECT @AuthorID = RoleID FROM dbo.RoleLU WHERE RoleName = 'Author'

/*Create temp table to hold BOE, Approver, Author Combination*/
DECLARE @BOEAppover TABLE
	(
		BOEID int PRIMARY KEY,
		ApprovalList varchar(500),
		Processed bit DEFAULT 0
		)
INSERT INTO @BOEAppover(BOEID)
SELECT 
	DISTINCT BUR.BOEID 
FROM [dbo].[BOE] B
	INNER JOIN [dbo].[BOEUserRole] BUR ON B.BOEID = BUR.BOEID
WHERE 
	B.WorkspaceID = @WorkspaceID AND
	BUR.RoleID = @ApproverID


WHILE EXISTS (SELECT 1 FROM @BOEAppover WHERE Processed = 0)
	BEGIN
		SELECT TOP 1 @BOEID = BOEID, @ApprovalList = NULL FROM @BOEAppover WHERE Processed = 0
		
	
		SELECT @ApprovalList = 
			COALESCE(@ApprovalList + ', ' ,'') + 
			CAST (ETIuserID AS varchar(10)) 
		FROM [dbo].[BOEUserRole] 
		WHERE 
			[BOEID] = @BOEID AND
			RoleID = @ApproverID

		
		UPDATE @BOEAppover
			SET ApprovalList = @ApprovalList,
				Processed = 1
		WHERE
			BOEID = @BOEID  AND
			Processed = 0
	
	END

	SELECT 
	   WBS.[WBSID] AS [WBSID]
      ,(WBS.[WBSNumber] + SPACE (1) + [WBSTitle]) AS [WBS]
      ,WBS.[UpdateDT] AS [WBS_UpdateDT]
      ,C.[CLINID] AS [CLINID]
      ,CASE 
		WHEN LEN(C.[CLINNumber] + SPACE (1) + '-' + SPACE (1) + C.[CLINTitle]) <= 50 
			THEN  C.[CLINNumber] + SPACE (1) + '-' + SPACE (1) + C.[CLINTitle]
		ELSE
			LEFT (C.[CLINNumber] + SPACE (1) + '-' + SPACE (1) + C.[CLINTitle], 50) + '...'
		END AS [CLIN] 
	  ,C.[CLINStartDate] AS [CLINStartDate]
	  ,C.[CLINEndDate] AS [CLINEndDate]	  
	  ,C.[UpdateDT] AS [CLIN_UpdateDT]
      ,B.[BOEID] AS [BOEID]
      ,B.[BOEStartDate] AS [BOEStartDate]
      ,B.[BOEEndDate] AS [BOEEndDate]
      ,B.[UpdateDT] AS [BOE_UpdateDT]
	   ,BUR.[ETIUserID] AS [Author]
	   ,BA.[ApprovalList] AS [Approvers]
	   ,BS.[BOEState] AS [BOEState]
	   ,W.[ContractStartDate] AS [ContractStartDate]
	   ,W.[ContractEndDate] AS [ContractEndDate]
 FROM [dbo].[BOE] B 
	INNER JOIN [dbo].[Workspace] W ON B.WorkspaceID = W.WorkspaceID
	INNER JOIN [dbo].[BOEStateLU] BS ON B.BOEStateID = BS.BOEStateID
	LEFT OUTER JOIN [dbo].[WBS_CLIN_BOE_XREF] X ON B.BOEID = X.BOEID
	LEFT OUTER JOIN [dbo].[WorkBreakdownStructure] WBS ON X.WBSID = WBS.WBSID
	LEFT OUTER JOIN [dbo].[CLIN] C ON X.CLINID = C.CLINID
	LEFT OUTER JOIN [dbo].[BOEUserRole] BUR ON B.BOEID = BUR.BOEID AND BUR.RoleID = @AuthorID 
	LEFT OUTER JOIN @BOEAppover BA ON B.BOEID = BA.BOEID
WHERE 
	B.WorkspaceID = @WorkspaceID

GO

