CREATE PROCEDURE [dbo].[getHistoricalMetricSearchBox]
(
@Search varchar(100)
)
AS
/******************************************************************************
**		 
**		Name: [getHistoricalMetricSearchBox]
**		Desc: Auto completes word from specific tables
**			
**		   
**		
**
**		Auth: Don Canuso
**		Date: 4/15/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		2/28/12		dcanuso				Hot Fix 7679 Add LaborHourMetric varchar(50)
*******************************************************************************/
SET NOCOUNT ON
SET @Search = '%' + @Search + '%'

SELECT Result.Search AS SearchResult
FROM (
	SELECT MetricTitle AS Search FROM dbo.Metric WHERE MetricTitle LIKE @Search
	UNION
	SELECT Discipline AS Search FROM dbo.Metric WHERE Discipline LIKE @Search
	UNION
	SELECT SourceProgramLongName AS Search FROM dbo.Metric WHERE SourceProgramLongName LIKE @Search
	UNION
	SELECT SourceProgramShortName AS Search FROM dbo.Metric WHERE SourceProgramShortName LIKE @Search
	UNION
	SELECT LaborHourMetric AS Search FROM dbo.Metric WHERE LaborHourMetric LIKE @Search
	) Result

GO

