CREATE PROCEDURE [dbo].[getMetricBySearch]
(
	@SearchCategory int,
	@Search nvarchar (200)
)
AS
/******************************************************************************
**		 
**		Name: [getMetricBySearch]
**		Desc: Returns MetricID using Search criteria
**				All words that are sent in need
**				to be found somewhere
**				So, as long as every word is found
**				in one of the searched fields, then it should
**				be returned.
**				So, need to look through each word.
**
**				Developer will be padding words with
**				"" and separating word phrases with
**				commas (,).
**		
**		
**				Search Category:
**					1. Not Validated
**					2. Validated
**					3. All Historical Metrics

**		Auth: Don Canuso
**		Date: 4/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		5/9/11		dcanuso				Because, in theory, a user can enter 
**										100 characters and because
**										the SQL code needs to have spaces, 
**										commas, and double quotes, I 
**										discussed with Developer and will
**										be updating parameters to allow 
**										more charcters - easiest to just double
**										Front end code will limit the input that
**										user will be able to enter
**										Good example is, the following 3-10 character
**										strings turns into 41 characters when you 
**										add commas, spaces, and double quotes
**										('"A123456789", "B123456789", "C123456789",')
**										Search parameter from 100 to 200 
**										Front end limit is still 100
**		7/5/11		dcanuso				To be consistent with Quick Search, changing
**										delimiter from , to ~
**										Also made some performance updates because
**										the results were taking 2 seconds to return
**										NOTE:
**										If additional performance enhancements
**										are needed, can remove @MeticSearch
**										and integrate it into main query search
**		2/28/12		dcanuso				Hot Fix 7679 Add @LaborHourMetric varchar(50)
*******************************************************************************/
SET NOCOUNT ON 

IF LEN(@Search) = 0
	BEGIN
		SELECT NULL AS MetricID
		RETURN
	END


IF RIGHT(@Search,1) <> '~' SET @Search = @Search + '~'

/*Create table to hold parsed words*/
DECLARE @WordSearch TABLE
	(
		Word varchar(200),
		Processed bit DEFAULT 0
	)

/*Split words*/
WHILE (SELECT CHARINDEX('~', @Search)) > 0
	BEGIN
	INSERT INTO @WordSearch (Word) 
		SELECT  '"' + REPLACE(RTRIM(LEFT (@Search, CHARINDEX('~', @Search)-1)), '"', '') + '"'
		SET @Search = RIGHT(@Search, LEN(@Search)- CHARINDEX('~', @Search))
	END


/*Variable to hold how many words are passed in*/
DECLARE @WordSearchCount int
SELECT @WordSearchCount = COUNT (Word) FROM @WordSearch

DECLARE @MeticSearch TABLE
	(
		MetricID int PRIMARY KEY,
		Found int DEFAULT 0
	)

	
/*Load Table with available Metrics*/
INSERT INTO @MeticSearch(MetricID)
SELECT MetricID
FROM dbo.Metric 
WHERE 
/*
	Search Category:
		1. Not Validated
		2. Validated
		3. All Historical Metrics

MetricStatusLU Table:
MetricStatusID	MetricStatus
1				Not Validated
2				Validated
*/
(
	(@SearchCategory = 1 AND MetricStatusID = 1) OR
	(@SearchCategory = 2 AND MetricStatusID = 2) OR
	(@SearchCategory = 3) 
)
	





/*Variable to hold current Word*/
DECLARE @CurrentWord varchar (200)

WHILE EXISTS (SELECT 1 FROM @WordSearch WHERE Processed = 0)
	BEGIN
		/*Obtain First Word to Search*/
		SELECT TOP 1 @CurrentWord = Word FROM @WordSearch WHERE Processed = 0

		/*Update List for Found Words*/
		UPDATE @MeticSearch
			SET Found = Found + 1
		FROM @MeticSearch MS
			INNER JOIN 
				(			
					SELECT  M.MetricID
					FROM dbo.Metric M
						INNER JOIN @MeticSearch MS ON M.MetricID = MS.MetricID
						INNER JOIN dbo.MOQTypeLU MT ON M.MOQTypeID = MT.MOQTypeID
						INNER JOIN dbo.ETIuser MetricOwner ON M.MetricOwnerETIUserID = MetricOwner.ETIUserID
						INNER JOIN dbo.ETIuser MetricMinedBy ON M.MetricMinedETIUserID = MetricMinedBy.ETIUserID
						LEFT OUTER JOIN dbo.LaborSourceLU LS ON M.LaborSourceID = LS.LaborSourceID
						LEFT OUTER JOIN dbo.UsageLU U ON M.UsageID = U.UsageID
					WHERE
							(
								CONTAINS (M.MetricTitle, @CurrentWord) OR
								CONTAINS (M.Discipline, @CurrentWord) OR
								CONTAINS (M.SourceProgramLongName, @CurrentWord) OR
								CONTAINS (M.SourceProgramShortName, @CurrentWord) OR
								CONTAINS (M.MajorComponentCharacteristic, @CurrentWord) OR								
								CONTAINS (M.ProgramMilestone, @CurrentWord) OR
								CONTAINS (U.Usage, @CurrentWord) OR																																								
								CONTAINS (LS.LaborSource, @CurrentWord) OR
								CONTAINS (M.MOQEquation, @CurrentWord) OR
								CONTAINS (MT.MOQType, @CurrentWord) OR
								CONTAINS (M.MOQText, @CurrentWord) OR
								CONTAINS (MetricOwner.DisplayName, @CurrentWord) OR
								CONTAINS (MetricMinedBy.DisplayName, @CurrentWord) OR
								CONTAINS (M.DataSourceLocation, @CurrentWord) OR
								CONTAINS (M.LaborHourMetric, @CurrentWord)
							)
					UNION
						SELECT  M.MetricID
						FROM dbo.Metric M
						WHERE 
							PATINDEX('%[^.0-9]%' , REPLACE(@CurrentWord,'"','')) = 0 /*There can be no letters to match ID*/ AND  
							M.MetricID = CAST (REPLACE(@CurrentWord,'"','') AS INT) 
					) Search ON MS.MetricID = Search.MetricID
				

			/*Update Words with Processed*/
			UPDATE @WordSearch 
				SET	Processed = 1
			WHERE
				Word = @CurrentWord
																
	END
	
		

SELECT M.MetricID AS MetricID
FROM dbo.Metric M
	INNER JOIN @MeticSearch MS ON M.MetricID = MS.MetricID
WHERE
	@WordSearchCount = MS.Found

GO

