CREATE PROCEDURE [dbo].[getWorkspaceRateUpdateFlag]
(
@WorkspaceID int 
)
AS
/******************************************************************************
**		 
**		Name:	[getWorkspaceRateUpdateFlag]
**		Desc:	Return the message that the user would see
**				is “Your rates are old. There are new rates available (as of XXX)
**				The very first system resource rate’s date is what we are looking for
**				
**				BOE Custom Fields:  https://isgs-gen.external.lmco.com/sites/Estimating_Init/
**				doclib14/Wireframes/BOE%20Custom%20Fields.mht
**				Resource Rates:  https://isgs-gen.external.lmco.com/sites/Estimating_Init/doclib14/
**				Wireframes/Resource%20Rates.mht
**		
**
**		Auth: Don Canuso
**		Date: 3/27/14
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
*******************************************************************************/

DECLARE @MaxLaborResourceRateDate datetime2(7) 
SELECT @MaxLaborResourceRateDate = MAX (UpdateDT) 
FROM dbo.LaborResourceRate 
/*SELECT @MaxLaborResourceRateDate*/


DECLARE  @ErrorMessage varchar (500) = 
'Your rates are old. There are new rates available as of ' + CAST (@MaxLaborResourceRateDate AS varchar(500))

IF NOT EXISTS 
	(
		SELECT WorkspaceID 
		FROM dbo.WorkspaceLockedLaborResourceRate
		WHERE WorkspaceID = @WorkspaceID
	)
BEGIN
/*Developer requested only Max Date gets returned*/
	SELECT NULL AS SystemResourceUpdateDate
	RETURN
END

IF EXISTS (
	SELECT * /*	SELECT WLRR.UpdateDT, LRR.UpdateDT*/
	FROM dbo.WorkspaceLockedLaborResourceRate WLRR
			INNER JOIN dbo.LaborResourceRate LRR ON 
				WLRR.LaborResourceRateID = LRR.LaborResourceRateID 
	WHERE 
			WLRR.WorkspaceID = @WorkspaceID AND
			WLRR.UpdateDT <> LRR.UpdateDT
		)
BEGIN 
	SELECT @MaxLaborResourceRateDate AS SystemResourceUpdateDate
	RETURN

END
ELSE
	BEGIN
		SELECT NULL AS SystemResourceUpdateDate
		RETURN
	END

GO

