CREATE PROCEDURE [dbo].[insertMetricAdminUserRole]
(
	@ETIUserID int,
	/*@ETIGroupID int,*/
	@RoleID int,
	@MetricAdminGroupID int,
	@UpdateDT datetime2(7)
)
AS
/******************************************************************************
**		 
**		Name: insertMetricAdminUserRole
**		Desc: Inserts a record into the dbo.MetricAdminUserRole table
**			
**		
**
**		Auth: Don Canuso
**		Date: 3/2/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		11/20/13	dcanuso				Permission Story - Remove ETI Group ID
**		12/4/13		dcanuso				WI 24910
*******************************************************************************/
SET NOCOUNT ON 

DECLARE	@ErrorMessage varchar (500)
IF EXISTS (SELECT 1 FROM dbo.BOEPotentialRole WHERE RoleID = 9 AND ETIUserID = @ETIUserID)
BEGIN

	SET @ErrorMessage =   'You can not add any other roles to a user that has the Subcontractor Author role '
	RAISERROR (
		@ErrorMessage, -- Message text.
        11, -- Severity,/*Severity Changed to 11*/
		1 -- State,
		)
	RETURN
END

IF NOT EXISTS (
				SELECT 1 
				FROM dbo.MetricAdminUserRole
				WHERE ETIUserID = @ETIUserID AND
						/*IsNull(ETIGroupID,0) = IsNull(@ETIGroupID,0) AND*/
						RoleID = @RoleID AND
						MetricAdminGroupID = @MetricAdminGroupID
				)
	BEGIN
	
	SET @UpdateDT = GETDATE()

	INSERT INTO [dbo].[MetricAdminUserRole]
           (
            [ETIUserID]
          /* ,[ETIGroupID]*/
           ,[RoleID]
           ,[MetricAdminGroupID]
           ,[UpdateDT])
     VALUES
           (
            @ETIUserID
         /*  ,@ETIGroupID*/
           ,@RoleID
           ,@MetricAdminGroupID
           ,@UpdateDT
           )

	END
GO

