*******************************************************************************/
SET NOCOUNT ON
/*Load Foresight Data
Program Hierarchy
Business Area
Product Line
Line of Business
Program
*/

TRUNCATE TABLE [dbo].[foresightProgram]
/*
UPDATE [dbo].[foresightProgram]
   SET [ProgramID] = F.ProgramID
      ,[ProgramName] = F.ProgramName
      ,[LOBID] = F.LOBID
      ,[LOB] = F.LOB
      ,[LineOfBusinessLongName] = F.LineOfBusinessLongName
      ,[lob_URLalias] = F.lob_URLalias
      ,[PLID] = F.PLID
