      ,[ProductLineLongName] = F.ProductLineLongName
      ,[pl_URLalias] = F.pl_URLalias
      ,[BAID] = F.BAID
      ,[BA] = F.BA
      ,[BusinessAreaLongName] = F.BusinessAreaLongName
      ,[ba_URLalias] = F.ba_URLalias
      ,[ProgramManagerName] = F.ProgramManagerName
      ,[ProgramManagerPhone] = F.ProgramManagerPhone
      ,[ProgramManagerEmail] = F.ProgramManagerEmail
