      ,[Country] = F.Country
      ,[ContractType] = F.ContractType
      ,[ContractValue] = F.ContractValue
      ,[ContractRole] = F.ContractRole
      ,[PoPStart] = F.PoPStart
      ,[PoPEnd] = F.PoPEnd
      ,[CustomerName] = F.CustomerName
      ,[CustomerType] = F.CustomerType
      ,[ProgramStatus] = F.ProgramStatus
      ,[EPRSID] = F.EPRSID
      ,[FiscalLedgerId] = F.FiscalLedgerId
      ,[isParent] = F.isParent
      ,[ParentProgramID] = F.ParentProgramID
      ,[IsReportable] = F.IsReportable
      ,[isFocusProgram] = F.isFocusProgram
      ,[isPriorityProgram] = F.isPriorityProgram
      ,[ProgramLongName] = F.ProgramLongName
      ,[URLalias] = F.URLalias
      ,[ProgramDataInsertDate] = F.ProgramDataInsertDate
      ,[ProgramDeletedDate] = F.ProgramDeletedDate
      ,[PercentDevelopment] = F.PercentDevelopment
      ,[PercentProduction] = F.PercentProduction
      ,[PercentResearch] = F.PercentResearch
      ,[PercentServices] = F.PercentServices
      ,[PercentSustainment] = F.PercentSustainment
      ,[CustomerPOC] = F.CustomerPOC
        ,[FiscalLedger] = F.FiscalLedger
  FROM [VFASSQL25\ARCHSVCSPROD2012].[ForesightEnterpriseDashboard].[dbo].[v_Generations_Program_Info] F
      INNER JOIN dbo.foresightProgram FP ON F.ProgramID = FP.ProgramID
      where F.PoPStart is not null and F.POPEnd is not null
