           ,[ProgramManagerEmail]
           ,[ProgramScope]
           ,[ProgramLongDescription]
           ,[City]
           ,[State]
           ,[Country]
           ,[ContractType]
           ,[ContractValue]
           ,[ContractRole]
           ,[PoPStart]
           ,[PoPEnd]
           ,[CustomerName]
           ,[CustomerType]
           ,[ProgramStatus]
           ,[EPRSID]
           ,[FiscalLedgerId]
           ,[isParent]
           ,[ParentProgramID]
           ,[IsReportable]
           ,[isFocusProgram]
           ,[isPriorityProgram]
           ,[ProgramLongName]
           ,[URLalias]
           ,[ProgramDataInsertDate]
