      ,F.[PLID]
      ,F.[PL]
      ,F.[ProductLineLongName]
      ,F.[pl_URLalias]
      ,F.[BAID]
      ,F.[BA]
      ,F.[BusinessAreaLongName]
      ,F.[ba_URLalias]
      ,F.[ProgramManagerName]
      ,F.[ProgramManagerPhone]
      ,F.[ProgramManagerEmail]
      ,F.[ProgramScope]
      ,F.[ProgramLongDescription]
      ,F.[City]
      ,F.[State]
      ,F.[Country]
      ,F.[ContractType]
      ,F.[ContractValue]
      ,F.[ContractRole]
      ,F.[PoPStart]
      ,F.[PoPEnd]
      ,F.[CustomerName]
      ,F.[CustomerType]
      ,F.[ProgramStatus]
      ,F.[EPRSID]
      ,F.[FiscalLedgerId]
      ,F.[isParent]
      ,F.[ParentProgramID]
      ,F.[IsReportable]
      ,F.[isFocusProgram]
      ,F.[isPriorityProgram]
      ,F.[ProgramLongName]
      ,F.[URLalias]
      ,F.[ProgramDataInsertDate]
      ,F.[ProgramDeletedDate]
      ,F.[PercentDevelopment]
      ,F.[PercentProduction]
      ,F.[PercentResearch]
      ,F.[PercentServices]
      ,F.[PercentSustainment]
      ,F.[CustomerPOC]
        ,F.[FiscalLedger]
  FROM [VFASSQL25\ARCHSVCSPROD2012].[ForesightEnterpriseDashboard].[dbo].[v_Generations_Program_Info] F
      LEFT OUTER JOIN dbo.foresightProgram FP ON F.ProgramID = FP.ProgramID
WHERE 
	FP.ProgramID IS NULL AND
	F.PoPStart IS NOT NULL AND 
	F.POPEnd IS NOT NULL AND 
		(
			F.[ProgramStatus] IN ('A', 'H') OR
				(
					F.[ProgramStatus] = 'I' AND 
					F.[LOB] = 'Commercial' AND 
					F.[PL] = 'Commercial'
				)
		)






INSERT INTO [dbo].[BusinessArea]
           ([BusinessAreaName]
           ,[BusinessAreaLongName]
           ,[BusinessAreaURL]
           ,[ForesightBusinessAreaID]
           ,[IsActive]
           )
SELECT DISTINCT
      P.[BA]
      ,P.[BusinessAreaLongName]
      ,P.[ba_URLalias]
      ,P.[BAID]
      ,1
FROM [dbo].[foresightProgram] P
      LEFT OUTER JOIN [dbo].[BusinessArea] BA ON P.BAID = BA.ForesightBusinessAreaID
WHERE 
	BA.ForesightBusinessAreaID IS NULL AND
	(
		P.[ProgramStatus] IN ('A', 'H') 
		OR
		(
			P.[ProgramStatus] = 'I' AND 
			P.[LOB] = 'Commercial' AND 
			P.[PL] = 'Commercial'
		)
	)



UPDATE [dbo].[BusinessArea]
   SET [BusinessAreaName] = P.[BA]
      ,[BusinessAreaLongName] = P.[BusinessAreaLongName]
      ,[BusinessAreaURL] = P.[ba_URLalias]
      ,[IsActive] = 1
FROM [dbo].[BusinessArea] BA 
      INNER JOIN [dbo].[foresightProgram] P ON P.BAID = BA.ForesightBusinessAreaID
WHERE 
      BA.[BusinessAreaName] <> P.[BA] OR
      BA.[BusinessAreaLongName] <> P.[BusinessAreaLongName] OR
    BA.[BusinessAreaURL] <> P.[ba_URLalias] OR
    BA.[IsActive] IS NULL





INSERT INTO [dbo].[ProductLine]
           ([ProductLineName]
           ,[ProductLineLongName]
           ,[ProductLineURL]
           ,[BusinessAreaID]
           ,[ForesightProductLineID]
           ,[IsActive]
           )
SELECT DISTINCT 
         fP.[PL]
      ,fP.[ProductLineLongName]
      ,fP.[pl_URLalias]
      ,BA.BusinessAreaID     
      ,fP.[PLID]
      ,1
FROM [dbo].[foresightProgram] fP
      INNER JOIN dbo.BusinessArea BA ON fP.BAID = BA.ForesightBusinessAreaID
      LEFT OUTER JOIN dbo.ProductLine PL ON fP.PLID = PL.ForesightProductLineID
WHERE 
	PL.ForesightProductLineID IS NULL AND 
		(
			fP.[ProgramStatus] IN ('A', 'H') OR
				(
					FP.[ProgramStatus] = 'I' AND 
					FP.[LOB] = 'Commercial' AND 
					FP.[PL] = 'Commercial'
				)
		)



UPDATE [dbo].[ProductLine]
   SET [ProductLineName] = fP.[PL]
      ,[ProductLineLongName] = fP.[ProductLineLongName]
      ,[ProductLineURL] = fP.[pl_URLalias]
      ,[BusinessAreaID] = BA.BusinessAreaID
      ,[IsActive] =1
FROM dbo.ProductLine PL
      INNER JOIN [dbo].[foresightProgram] fP ON fP.PLID = PL.ForesightProductLineID
      INNER JOIN dbo.BusinessArea BA ON fP.BAID = BA.ForesightBusinessAreaID
WHERE
        PL.[ProductLineName] <> fP.[PL] OR
      PL.[ProductLineLongName] <> fP.[ProductLineLongName] OR
      PL.[ProductLineURL] <> fP.[pl_URLalias] OR
      PL.[BusinessAreaID] <> BA.BusinessAreaID OR
        PL.[IsActive] IS NULL




INSERT INTO [dbo].[LineOfBusiness]
           ([LineOfBusinessName]
           ,[LineOfBusinessLongName]
           ,[LineOfBusinessURL]
           ,[ProductLineID]
           ,[ForesightLineOfBusinessID]
           ,[IsActive]
           )
SELECT DISTINCT
       fP.[LOB]
      ,fP.[LineOfBusinessLongName]
      ,fP.[lob_URLalias]
      ,PL.ProductLineID
      ,fP.[LOBID]      
      ,1
FROM dbo.[foresightProgram] fP
      INNER JOIN dbo.ProductLine PL ON fP.PLID = PL.ForesightProductLineID
      LEFT OUTER JOIN dbo.LineOfBusiness LOB ON fP.LOBID = LOB.ForesightLineOfBusinessID
WHERE 
	LOB.ForesightLineOfBusinessID IS NULL AND 
	(
		fP.[ProgramStatus] IN ('A', 'H') OR
			(
				FP.[ProgramStatus] = 'I' AND 
				FP.[LOB] = 'Commercial' AND 
				FP.[PL] = 'Commercial'
			)
	)




UPDATE [dbo].[LineOfBusiness]
   SET [LineOfBusinessName] = fP.[LOB]
      ,[LineOfBusinessLongName] = fP.[LineOfBusinessLongName]
      ,[LineOfBusinessURL] = fP.[lob_URLalias]
      ,[ProductLineID] = PL.ProductLineID
      ,[IsActive] = 1
           
FROM dbo.LineOfBusiness LOB 
      INNER JOIN dbo.foresightProgram fP ON LOB.ForesightLineOfBusinessID = fP.LOBID
      INNER JOIN dbo.ProductLine PL ON fP.PLID = PL.ForesightProductLineID
WHERE
      LOB.[LineOfBusinessName] <> fP.[LOB] OR
    LOB.[LineOfBusinessLongName] <> fP.[LineOfBusinessLongName] OR
    LOB.[LineOfBusinessURL] <> fP.[lob_URLalias] OR
    LOB.[ProductLineID] <> PL.ProductLineID OR
    LOB.[IsActive] IS NULL



/*Handle Removed Items and thus Inactive*/
UPDATE dbo.BusinessArea
SET IsActive =
	CASE 
		WHEN B.BAID IS NULL THEN  0  
		WHEN B.BAID IS NOT NULL THEN  1
	END	
FROM dbo.BusinessArea A
      LEFT OUTER JOIN dbo.foresightProgram B
      ON    A.ForesightBusinessAreaID =   B.BAID   AND
			( 
				B.[ProgramStatus] IN ('A', 'H') OR
					(
						 B.[ProgramStatus] = 'I' AND 
						 B.[LOB] = 'Commercial' AND 
						 B.[PL] = 'Commercial'
					 )
			)
/*      WHERE 
      B.BAID IS NULL 
*/      

      

UPDATE dbo.LineOfBusiness
SET IsActive =
	CASE 
		WHEN B.LOBID IS NULL THEN  0  
		WHEN B.LOBID IS NOT NULL THEN  1
	END	
FROM dbo.LineOfBusiness A
      LEFT OUTER JOIN dbo.foresightProgram B
      ON    A.ForesightLineOfBusinessID =  B.LOBID AND
			(
				B.[ProgramStatus] IN ('A', 'H') OR
					(
						B.[ProgramStatus] = 'I' AND 
						B.[LOB] = 'Commercial' AND 
						B.[PL] = 'Commercial'
					)
			)
      
UPDATE dbo.ProductLine
SET  IsActive =
	CASE 
		WHEN B.PLID IS NULL THEN  0  
		WHEN B.PLID IS NOT NULL THEN  1
	END	
FROM dbo.ProductLine A
      LEFT OUTER JOIN dbo.foresightProgram B
      ON    A.ForesightProductLineID =    B.PLID  AND 			(
				B.[ProgramStatus] IN ('A', 'H') OR
					(
						B.[ProgramStatus] = 'I' AND 
						B.[LOB] = 'Commercial' AND 
						B.[PL] = 'Commercial'
					)
			)

/*For genBOE 2.0*/
UPDATE LineOfBusiness SET IsActive=0 WHERE LineOfBusinessName = 'None'
UPDATE ProductLine SET IsActive=0 WHERE ProductLineName = 'None'
UPDATE BusinessArea SET IsActive=0 WHERE BusinessAreaName = 'None'
GO

