DELETE FROM [dbo].[Resource]
	FROM [dbo].[Resource] R
		INNER JOIN [dbo].[ResourceList] RL ON R.ResourceListID = RL.ResourceListID
		INNER JOIN dbo.Workspace WS ON RL.ResourceListID = WS.ResourceListID
WHERE 
