/*WI 6304 */
IF EXISTS  (SELECT CASE 
			WHEN vWR.[WorkspaceResourceID] IS NOT NULL THEN vWR.[WorkspaceResourceID]
			ELSE vWR.[SystemResourceID]
			END 
		FROM [version].[WorkspaceResourceRate] vWR
			INNER JOIN [version].[Workspace] WS ON vWR.WorkspaceID = WS.WorkspaceID			
			LEFT OUTER JOIN [dbo].[Resource] WSR ON vWR.[WorkspaceResourceID] =  WSR.ResourceID
			LEFT OUTER JOIN [dbo].[Resource] SR ON  vWR.[SystemResourceID] =  SR.ResourceID
		WHERE 
			vWR.VersionID = @VersionID AND
			WS.VersionID = @VersionID AND 
			WS.WorkspaceID = @WorkspaceID AND
			(
				WSR.ResourceID IS NULL AND 
				SR.ResourceID IS NULL
			)
				)-- IS NOT NULL
		BEGIN
		
		SELECT 	DISTINCT	@ErrorMessage = 
				IsNull(@ErrorMessage,'WARNING: ') + 
				ErrorMessage.ErrorMessage
		FROM 
			(	SELECT 
				'ResourceID: ' + 
				CAST (vR.ResourceID AS varchar(10)) + 
				' Resource Name: ' + 
				vR.ResourceName + 
				' no longer exists.' + 
				CHAR(13) AS ErrorMessage
		FROM [version].[WorkspaceResourceRate] vWR
			INNER JOIN [version].[Resource] vR ON vWR.[WorkspaceResourceID] = vR.ResourceID
			INNER JOIN [version].[Workspace] WS ON vWR.WorkspaceID = WS.WorkspaceID			
			LEFT OUTER JOIN [dbo].[Resource] WSR ON vWR.[WorkspaceResourceID] =  WSR.ResourceID
			LEFT OUTER JOIN [dbo].[Resource] SR ON  vWR.[SystemResourceID] =  SR.ResourceID
		WHERE 
			vWR.VersionID = @VersionID AND
			WS.VersionID = @VersionID AND 
			WS.WorkspaceID = @WorkspaceID AND
			(
				WSR.ResourceID IS NULL AND 
				SR.ResourceID IS NULL
			) AND
			vR.VersionID = @VersionID 
		UNION						
			SELECT 
				'ResourceID: ' + 
				CAST (vR.ResourceID AS varchar(10)) + 
				' Resource Name: ' + 
				vR.ResourceName + 
				' no longer exists.' + 
				CHAR(13)  AS ErrorMessage
		FROM [version].[WorkspaceResourceRate] vWR
			INNER JOIN [version].[Resource] vR ON vWR.[SystemResourceID] = vR.ResourceID
			INNER JOIN [version].[Workspace] WS ON vWR.WorkspaceID = WS.WorkspaceID			
			LEFT OUTER JOIN [dbo].[Resource] WSR ON vWR.[WorkspaceResourceID] =  WSR.ResourceID
			LEFT OUTER JOIN [dbo].[Resource] SR ON  vWR.[SystemResourceID] =  SR.ResourceID
		WHERE 
			vWR.VersionID = @VersionID AND
			WS.VersionID = @VersionID AND 
			WS.WorkspaceID = @WorkspaceID AND
			(
				WSR.ResourceID IS NULL AND 
				SR.ResourceID IS NULL
			) AND
			vR.VersionID = @VersionID 
		) ErrorMessage				

						
		END




IF  EXISTS  (SELECT vLRR.LaborResourceRateID 
					FROM [version].[LaborResourceRate] vLRR
						INNER JOIN [version].[Resource] vS ON vLRR.SystemResourceID = vS.ResourceID
						INNER JOIN [version].[WorkspaceResourceRate] vWR ON vS.ResourceID = vWR.SystemResourceID
						INNER JOIN [version].[Workspace] WS ON vWR.WorkspaceID = WS.WorkspaceID
						LEFT OUTER JOIN [dbo].[LaborResourceRate] LRR ON vLRR.LaborResourceRateID = LRR.LaborResourceRateID
					WHERE 
						vLRR.VersionID = @VersionID AND
						vS.VersionID = @VersionID AND
						vWR.VersionID = @VersionID AND
						WS.VersionID = @VersionID AND 
						WS.WorkspaceID = @WorkspaceID AND
						LRR.LaborResourceRateID IS NULL
				)-- IS NOT NULL
		BEGIN

			SELECT DISTINCT	@ErrorMessage = 
				IsNull(@ErrorMessage,'WARNING: ') + 
				'LaborResourceRateID: ' + 
				CAST (vLRR.LaborResourceRateID  AS varchar(10)) + 
				' no longer exists.' + 
				CHAR(13) 
			FROM [version].[LaborResourceRate] vLRR
				INNER JOIN [version].[Resource] vS ON vLRR.SystemResourceID = vS.ResourceID
				INNER JOIN [version].[WorkspaceResourceRate] vWR ON vS.ResourceID = vWR.SystemResourceID
				INNER JOIN [version].[Workspace] WS ON vWR.WorkspaceID = WS.WorkspaceID
				LEFT OUTER JOIN [dbo].[LaborResourceRate] LRR ON vLRR.LaborResourceRateID = LRR.LaborResourceRateID
			WHERE 
				vLRR.VersionID = @VersionID AND
				vS.VersionID = @VersionID AND
				vWR.VersionID = @VersionID AND
				WS.VersionID = @VersionID AND 
				WS.WorkspaceID = @WorkspaceID AND
				LRR.LaborResourceRateID IS NULL						
		END



