CREATE PROCEDURE [dbo].[updateWorkspaceAutoCalculateDTS]
(
@WorkspaceID int,
@DTSAutoCalculateID int,
@UpdateDT datetime2,
@RestrictDTS bit
)
AS
/******************************************************************************
**		 
**		Name:	[updateWorkspaceAutoCalculateDTS]
**		Desc:	Update Workspace and sets the Auto Calculate DTS Option
**			
**		DTSAutoCalculateID	DTSAutoCalculate
**		1					No
**		2					In each BOE
**		3					In summary BOEs
**
**		Auth: Don Canuso
**		Date: 8/24/2011
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		4/6/15		dcanuso				@RestrictDTS Added - WI35834
*******************************************************************************/
SET NOCOUNT ON 
DECLARE @ErrorMessage varchar (500)

IF (SELECT UpdateDT FROM dbo.Workspace WHERE WorkspaceID = @WorkspaceID) = @UpdateDT
	BEGIN			
		UPDATE dbo.Workspace
			SET DTSAutoCalculateID = @DTSAutoCalculateID,
				[RestrictDTS] = @RestrictDTS
		WHERE
			WorkspaceID = @WorkspaceID
	END
ELSE
	BEGIN
		SET @ErrorMessage =   'The row in Workspace with WorkspaceID ' + CAST (@WorkspaceID AS VARCHAR (10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
	END
GO

