CREATE PROCEDURE [dbo].[upsertBOELaborType]
(
@BOELaborTypeID int,
@ResourceID int,
@PerformingOrganizationID int,
@BOELaborTypeStartDate date,
@BOELaborTypeEndDate date,
@SpreadCurveID int,
@PercentSpread DECIMAL (38,6),
@ValueSpread DECIMAL (18, 6),
