--inner join ETIuser u on br.ETIUserID = u.ETIUserID
-- WHERE br.RoleID <> 9 AND u.NTID='ipecoor2'

IF @RoleID <> 9
BEGIN
IF EXISTS (SELECT 1 FROM dbo.BOEPotentialRole WHERE RoleID = 9 AND ETIUserID = @ETIUserID AND @RoleID <> 9)
BEGIN

