*******************************************************************************/
SET NOCOUNT ON 

DECLARE @InsertedBOETaskElement AS Table (BOETaskElementID int)


IF @BOETaskElementID  < 0  /*Insert Record*/
	BEGIN
	SET @UpdateDT = GETDATE()
	INSERT INTO [dbo].[BOETaskElement]
           ([TaskID]
           ,[TaskTitle]
           ,[TaskDescription]
           ,[TaskStartDate]
           ,[TaskEndDate]
           ,[MOQHoursEquation]
           ,[MOQCostEquation]
           ,[MOQText]
           ,[MOQTypeID]
           ,[BOEID]
           ,[LaborTypeWarningFlag]
           ,[IMS_ID]
           ,[TaskElementTypeID]
           ,[UpdateDT]
		   ,[SortOrderID]
		   )
     OUTPUT inserted.BOETaskElementID INTO @InsertedBOETaskElement
     VALUES
           (
            @TaskID
           ,@TaskTitle
           ,@TaskDescription
           ,@TaskStartDate
           ,@TaskEndDate
           ,@MOQHoursEquation
           ,@MOQCostEquation
           ,@MOQText
           ,@MOQTypeID
           ,@BOEID
           ,@LaborTypeWarningFlag
           ,@IMS_ID
           ,@TaskElementTypeID
           ,@UpdateDT
		   ,@SortOrderID
            ) 
            
	SELECT @BOETaskElementID = BOETaskElementID FROM @InsertedBOETaskElement
	


END

ELSE
	BEGIN
		IF (SELECT UpdateDT FROM [dbo].[BOETaskElement] WHERE BOETaskElementID = @BOETaskElementID) = @UpdateDT
		BEGIN
			SET @UpdateDT = GetDate()
			
			 
			UPDATE [dbo].[BOETaskElement]
				SET 
					[TaskID] = @TaskID,
					[TaskTitle] = @TaskTitle,
					[TaskDescription] = @TaskDescription,
					[TaskStartDate] = @TaskStartDate,
					[TaskEndDate] = @TaskEndDate,
					[MOQHoursEquation] = @MOQHoursEquation,
					[MOQCostEquation] = @MOQCostEquation,
					[MOQText] = @MOQText,
					[MOQTypeID] = @MOQTypeID,
					[BOEID] = @BOEID,
					[LaborTypeWarningFlag] = @LaborTypeWarningFlag,
					[IMS_ID] = @IMS_ID,
					[TaskElementTypeID] = @TaskElementTypeID,
					[UpdateDT] = @UpdateDT,
					[SortOrderID] = @SortOrderID
			WHERE
				BOETaskElementID = @BOETaskElementID
				

		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =  'The row in BOETaskElement with BOETaskElementID ' + CAST(@BOETaskElementID AS varchar(10)) +  ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
		END
END

IF @@ERROR = 0
	SELECT @BOETaskElementID AS BOETaskElementID
