CREATE PROCEDURE [dbo].[upsertHistoricalMetric]
(
@MetricID int,
@MetricTitle varchar(100),
@Discipline varchar(100),
@MetricAdminGroupID int,
@SourceProgramLongName varchar(100),
@SourceProgramShortName varchar(50),
@MajorComponentCharacteristic varchar (500),
@ProgramMilestone varchar (50),
@UsageID int,
@LaborSourceID int,
@Size varchar (200),
@LaborHours varchar (200),
@AverageLaborType varchar (20),
@MOQEquation varchar (250),
@MOQTypeID int,
