@MetricStatusID int,
@MetricOwnerETIUserID int,
@MetricMinedETIUserID int,
@MetricMinedDate date,
@MetricValidatedETIUserID int,
@MetricValidatedDate date,
@MetricSupportingDataETIUserID int,
@MetricSupportingDataDate date,
@CustomerApprovalRequiredFlag bit,
@DataSourceLocation varchar (500),
@UpdatedByETIUserID int,
