@UpdateDT datetime2(7)
)
AS
/******************************************************************************
**		 
**		Name:	[upsertHistoricalMetric]
**		Desc:	Insert/Update Historical Metrics
**			
**		
**
**		Auth: Don Canuso
**		Date: 4/14/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		7/11/11		DCANUSO				SIZE AND LABOR HOUR INCREASED TO 200 PER WI
**										Usage chaned to Metric Type
**		10/24/11	dcanuso				The following parameters have changed from
**										datetime2 to date
**										@MetricMinedDate date
**										@MetricValidatedDate date
**										@MetricSupportingDataDate date
**		2/28/12		dcanuso				Hot Fix 7679 Add @LaborHourMetric varchar(50)
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @ErrorMessage varchar (500)

DECLARE @Inserted AS Table (ID int)


IF @MetricID  < 0  /*Insert Record*/
	BEGIN
	
	SET @UpdateDT = GETDATE()
	
	INSERT INTO [dbo].[Metric]
           ([MetricTitle]
           ,[Discipline]
           ,[MetricAdminGroupID]
           ,[SourceProgramLongName]
           ,[SourceProgramShortName]
           ,[MajorComponentCharacteristic]
           ,[ProgramMilestone]
           ,[UsageID]
           ,[LaborSourceID]
           ,[Size]
           ,[LaborHours]
           ,[AverageLaborType]
           ,[MOQEquation]
           ,[MOQTypeID]
           ,[MOQText]
           ,[MetricStatusID]
           ,[MetricOwnerETIUserID]
           ,[MetricMinedETIUserID]
           ,[MetricMinedDate]
           ,[MetricValidatedETIUserID]
           ,[MetricValidatedDate]
           ,[MetricSupportingDataETIUserID]
           ,[MetricSupportingDataDate]
           ,[CustomerApprovalRequiredFlag]
           ,[DataSourceLocation]
           ,[MetricInUse]
           ,[UpdatedByETIUserID]
           ,[LaborHourMetric]
           ,[UpdateDT])
     OUTPUT inserted.MetricID INTO @Inserted
     VALUES
			(@MetricTitle,
			@Discipline,
			@MetricAdminGroupID,
			@SourceProgramLongName,
			@SourceProgramShortName,
			@MajorComponentCharacteristic,
			@ProgramMilestone,
			@UsageID,
			@LaborSourceID,
			@Size,
			@LaborHours,
			@AverageLaborType,
			@MOQEquation,
			@MOQTypeID,
			@MOQText,
			@MetricStatusID,
			@MetricOwnerETIUserID,
			@MetricMinedETIUserID,
			@MetricMinedDate,
			@MetricValidatedETIUserID,
			@MetricValidatedDate,
			@MetricSupportingDataETIUserID,
			@MetricSupportingDataDate,
			@CustomerApprovalRequiredFlag,
			@DataSourceLocation,
			0, /*On Insert Metric can not be in Use*/
			@UpdatedByETIUserID,
			@LaborHourMetric,
			@UpdateDT)

	SELECT @MetricID = ID FROM @Inserted
	
	
END	
ELSE
	/*Update*/
	BEGIN
		IF (SELECT UpdateDT FROM dbo.Metric WHERE MetricID = @MetricID) = @UpdateDT
			BEGIN
			
				SET @UpdateDT = GETDATE()
				
				
				UPDATE [dbo].[Metric]
				   SET [MetricTitle] = @MetricTitle
					  ,[Discipline] = @Discipline
					  ,[MetricAdminGroupID] = @MetricAdminGroupID
					  ,[SourceProgramLongName] = @SourceProgramLongName
					  ,[SourceProgramShortName] = @SourceProgramShortName
					  ,[MajorComponentCharacteristic] = @MajorComponentCharacteristic
					  ,[ProgramMilestone] = @ProgramMilestone
					  ,[UsageID] = @UsageID
					  ,[LaborSourceID] = @LaborSourceID
					  ,[Size] = @Size
					  ,[LaborHours] = @LaborHours
					  ,[AverageLaborType] = @AverageLaborType
					  ,[MOQEquation] = @MOQEquation
					  ,[MOQTypeID] = @MOQTypeID
					  ,[MOQText] = @MOQText
					  ,[MetricStatusID] = @MetricStatusID
					  ,[MetricOwnerETIUserID] = @MetricOwnerETIUserID
					  ,[MetricMinedETIUserID] = @MetricMinedETIUserID
					  ,[MetricMinedDate] = @MetricMinedDate
					  ,[MetricValidatedETIUserID] = @MetricValidatedETIUserID
					  ,[MetricValidatedDate] = @MetricValidatedDate
					  ,[MetricSupportingDataETIUserID] = @MetricSupportingDataETIUserID
					  ,[MetricSupportingDataDate] = @MetricSupportingDataDate
					  ,[CustomerApprovalRequiredFlag] = @CustomerApprovalRequiredFlag
					  ,[DataSourceLocation] = @DataSourceLocation
					  ,[UpdatedByETIUserID] = @UpdatedByETIUserID
					  ,[LaborHourMetric] = @LaborHourMetric
					  ,[UpdateDT] = @UpdateDT
				 WHERE MetricID = @MetricID
				 
				   
END
ELSE
			BEGIN
				
				SET @ErrorMessage =   'The row in Metric with MetricID ' + CAST(@MetricID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
