CREATE PROCEDURE [dbo].[upsertLaborResourceRate]
(
@LaborResourceRateID [int],
@UpdateDT [datetime2](7),
@SystemResourceID [int],
@LaborResourceRateStartDate [date],
@LaborResourceRateEndDate [date],
@ResourceRate [decimal](5, 2)
)
AS
/******************************************************************************
**		 
**		Name: [upsertLaborResourceRate]
**		Desc: Insert/Update data in System Admin Labor 
**				Resource Rate and sets In Use Flag for Resource
**			
**		
**
**		Auth: Don Canuso
**		Date: 11/29/2011
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		12/13/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		1/17/12		dcanuso				Changes to the Design of WRR/LRR/Locking
**		2/7/12		dcanuso				Changes to InUse
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		1/17/13		dcanuso				WI 14477: If add new Labor Resource Rate, 
**										for every row associated with the unique 
**										resource, add a rate row. This guarantees old
**										and new workspaces get a rate
**		1/21/13		dcanuso				WI 14477
**										Summation of discussion with Linda and Don (and Dave):
**										Scenario:  A workspace is using a system resource with 
**										a rate associated with it.  If the system resource is 
**										updated, a new system resource record is created and 
**										a copy of the rate is created and will point to the 
**										new system resource record.  If the rate is updated, 
**										then all rate records with the same system resource 
**										name will be updated to contain the new rate. "
*******************************************************************************/
SET NOCOUNT ON 
SET arithabort ON

DECLARE	@Inserted AS Table (LaborResourceRateID int)

IF @LaborResourceRateID < 0  /*Insert Record*/

	BEGIN

	SET @UpdateDT = GetDate()

	INSERT INTO [dbo].[LaborResourceRate]
           ([UpdateDT]
           ,[SystemResourceID]
           ,[LaborResourceRateStartDate]
           ,[LaborResourceRateEndDate]
           ,[ResourceRate]
           )
     OUTPUT inserted.LaborResourceRateID INTO @Inserted
     VALUES
           (@UpdateDT
           ,@SystemResourceID
           ,@LaborResourceRateStartDate
           ,@LaborResourceRateEndDate
           ,@ResourceRate
           )

	SELECT 	@LaborResourceRateID = LaborResourceRateID FROM @Inserted
	
	/*WI14477*/
	DECLARE @MatchingResoures TABLE
	(
		ResourceID int
	)
	INSERT INTO @MatchingResoures
	SELECT M.ResourceID--R.ResourceID
	FROM [dbo].[Resource] R
		INNER JOIN [dbo].[Resource] M ON
			R.ResourceName = M.ResourceName AND
			R.SegmentRegion = M.SegmentRegion AND
			R.LaborType = M.LaborType AND
			R.SegmentID = M.SegmentID AND
			R.CostElementID = M.CostElementID
	WHERE
		R.ResourceID = @SystemResourceID AND
		R.ResourceListID = 1 AND
		M.ResourceListID = 1 AND
		R.ResourceID <> M.ResourceID
		
		
	INSERT INTO [dbo].[LaborResourceRate]
           ([UpdateDT]
           ,[SystemResourceID]
           ,[LaborResourceRateStartDate]
           ,[LaborResourceRateEndDate]
           ,[ResourceRate]
           )
	SELECT
            @UpdateDT
           ,M.ResourceID /*@SystemResourceID*/
           ,@LaborResourceRateStartDate
           ,@LaborResourceRateEndDate
           ,@ResourceRate
	FROM @MatchingResoures M           
          




		


END

ELSE
	BEGIN
			IF (SELECT UpdateDT FROM [dbo].[LaborResourceRate] WHERE LaborResourceRateID = @LaborResourceRateID) = @UpdateDT
			BEGIN	
			

				DECLARE	
					@CurrentLaborResourceRateStartDate [date],
					@CurrentLaborResourceRateEndDate [date],
					@CurrentResourceRate [decimal](5, 2)
				
				SELECT
					@CurrentLaborResourceRateStartDate = LaborResourceRateStartDate,
					@CurrentLaborResourceRateEndDate = LaborResourceRateEndDate,
					@CurrentResourceRate = ResourceRate
				FROM [dbo].[LaborResourceRate]
				WHERE LaborResourceRateID = @LaborResourceRateID

			SET @UpdateDT = GetDate()

			UPDATE [dbo].[LaborResourceRate]
			   SET [UpdateDT] = @UpdateDT
--				  ,[SystemResourceID] = @SystemResourceID
				  ,[LaborResourceRateStartDate] = @LaborResourceRateStartDate
				  ,[LaborResourceRateEndDate] = @LaborResourceRateEndDate
				  ,[ResourceRate] = @ResourceRate
			 WHERE LaborResourceRateID = @LaborResourceRateID






			UPDATE [dbo].[LaborResourceRate]
			   SET [UpdateDT] = @UpdateDT
				  ,[LaborResourceRateStartDate] = @LaborResourceRateStartDate
				  ,[LaborResourceRateEndDate] = @LaborResourceRateEndDate
				  ,[ResourceRate] = @ResourceRate
			FROM [dbo].[LaborResourceRate] U_LRR 
				INNER JOIN
					(
						SELECT 
							LRR.LaborResourceRateID,
							LRR.LaborResourceRateStartDate,
							LRR.LaborResourceRateEndDate,
							LRR.SystemResourceID AS OriginatingSystemResourceID,
							MR.ResourceID AS SystemResourceID 
						FROM [dbo].[LaborResourceRate] LRR 
						INNER JOIN [dbo].[Resource] R ON LRR.SystemResourceID = R.ResourceID
						INNER JOIN [dbo].[Resource] MR ON R.ResourceName = MR.ResourceName
						INNER JOIN
							(
								SELECT DISTINCT SystemResourceID
								FROM dbo.WorkspaceResource WR
									INNER JOIN dbo.Workspace W ON WR.WorkspaceID = W.WorkspaceID
								WHERE
									/*
									1	Initialization
									2	Working
									*/
									W.WorkspaceStateID IN (1,2)
							) WSR ON MR.ResourceID = WSR.SystemResourceID
						WHERE
							LRR.LaborResourceRateID = @LaborResourceRateID AND	
							LRR.SystemResourceID = @SystemResourceID AND							
							R.ResourceListID = 1 AND
							MR.ResourceListID = 1 AND
							R.ResourceID <> MR.ResourceID 							
					) LRR ON 
						U_LRR.SystemResourceID = LRR.SystemResourceID AND
						U_LRR.LaborResourceRateStartDate = @CurrentLaborResourceRateStartDate AND
						U_LRR.LaborResourceRateEndDate = @CurrentLaborResourceRateEndDate AND
						U_LRR.ResourceRate = @CurrentResourceRate
						



			
					
		END
			ELSE
			BEGIN
				DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in LaborResourceRate with LaborResourceRateID ' + CAST(@LaborResourceRateID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
			END
			
	END

IF @@ERROR = 0
	SELECT @LaborResourceRateID AS LaborResourceRateID
GO

