CREATE PROCEDURE [dbo].[upsertMaterial]
(
@MaterialID int,
@PartProfile varchar(25),
@PartProfileDescription varchar(250),
@SegmentID int,
@ExpendDate date,
@ExpendCost money,
@MaterialTaskElementID int,
@ResourceID int,
@UpdateDT datetime2(7)
)
AS
/******************************************************************************
**		 
**		Name: upsertMaterial
**		Desc: Insert/Update data into Material Section of BOE/Material
**			
**		
**
**		Auth: Don Canuso
**		Date: 6/22/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		7/6/11		dcanuso				Added Resource ID
**		11/25/11	dcanuso				InUse Updated
**		12/13/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		2/6/12		dcanuso				More changes to InUse Processing
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
*******************************************************************************/
SET NOCOUNT ON 

DECLARE	@InsertedMaterial AS Table (MaterialID int)

IF @MaterialID < 0  /*Insert Record*/

	BEGIN

	SET @UpdateDT = GetDate()

INSERT INTO [dbo].[Material]
           ([PartProfile]
           ,[PartProfileDescription]
           ,[SegmentID]
           ,[ExpendDate]
           ,[ExpendCost]
           ,[MaterialTaskElementID]
           ,[ResourceID]
           ,[UpdateDT])          
     OUTPUT inserted.MaterialID INTO @InsertedMaterial
     VALUES
           (@PartProfile
           ,@PartProfileDescription
           ,@SegmentID
           ,@ExpendDate
           ,@ExpendCost
           ,@MaterialTaskElementID
           ,@ResourceID
           ,@UpdateDT)


	SELECT 	@MaterialID = MaterialID FROM @InsertedMaterial
	
	/*Update In Use Flag*/
/*	EXECUTE [dbo].[updateResourceInUseFlagByResourceID] @ResourceID*/
	
END

ELSE
	BEGIN
			IF (SELECT UpdateDT FROM [dbo].[Material] WHERE MaterialID = @MaterialID) = @UpdateDT
			BEGIN	
			
			/*Variables Used for InUse Function*/
/*			DECLARE		@CurrentResourceID int
			
			SELECT	@CurrentResourceID  = ResourceID
			FROM [dbo].[Material]
			WHERE MaterialID = @MaterialID*/
			
			SET @UpdateDT = GetDate()
			
			UPDATE [dbo].[Material]
			   SET [PartProfile] = @PartProfile
				  ,[PartProfileDescription] = @PartProfileDescription
				  ,[SegmentID] = @SegmentID
				  ,[ExpendDate] = @ExpendDate
				  ,[ExpendCost] = @ExpendCost
				  ,[MaterialTaskElementID] = @MaterialTaskElementID
				  ,[ResourceID] = @ResourceID
				  ,[UpdateDT] = @UpdateDT
			WHERE 
				MaterialID = @MaterialID
				
				/*Update In Use Flag*/
				/*EXECUTE [dbo].[updateResourceInUseFlagByResourceID] @ResourceID
				EXECUTE [dbo].[updateResourceInUseFlagByResourceID] @CurrentResourceID*/
				
					
		END
			ELSE
			BEGIN
				DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in Material with MaterialID ' + CAST(@MaterialID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
			END
			
	END

IF @@ERROR = 0
	SELECT @MaterialID AS MaterialID
GO

