CREATE PROCEDURE [dbo].[upsertMaterialCustomFieldValue]
(
@MCFVID [int],
@MaterialID [int],
@CustomFieldValueID [int],
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: upsertMaterialCustomFieldValue
**		Desc: Insert/Update the Custom Field Value for the Material
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/17/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		12/13/11	dcanuso				WI 6166
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @InsertedMaterialCustomFieldValue AS Table (MCFVID int)



IF @MCFVID  < 0  /*Insert Record*/
	BEGIN

	SET @UpdateDT = GETDATE()
	
	INSERT INTO [dbo].[MaterialCustomFieldValueXREF]
           ([MaterialID]
           ,[CustomFieldValueID]
           ,[UpdateDT])
     OUTPUT inserted.MCFVID INTO @InsertedMaterialCustomFieldValue
     VALUES
           (
           @MaterialID,
           @CustomFieldValueID,
           @UpdateDT
           )
           
	SELECT @MCFVID = MCFVID FROM @InsertedMaterialCustomFieldValue
	
	UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = 1
	WHERE CustomFieldValueID = @CustomFieldValueID
END

ELSE
	BEGIN
		IF (SELECT UpdateDT FROM [dbo].[MaterialCustomFieldValueXREF] WHERE MCFVID = @MCFVID) = @UpdateDT
		BEGIN
			SET @UpdateDT = GetDate()
			
			DECLARE @OriginalCustomFieldValueID int

			SELECT @OriginalCustomFieldValueID = CustomFieldValueID
			FROM dbo.MaterialCustomFieldValueXREF 
			WHERE MCFVID = @MCFVID
			
			
			UPDATE [dbo].[MaterialCustomFieldValueXREF]
				SET [CustomFieldValueID] = @CustomFieldValueID,
					[UpdateDT] = @UpdateDT
			WHERE MCFVID = @MCFVID

			IF @OriginalCustomFieldValueID <> @CustomFieldValueID
				BEGIN
				/*Only should be looking within the scope
				of the Custom Field, so if the scope is Material
				then only look in MaterialCustomFieldValueXREF
				
				Set Flag to 0 when it is the last one
				*/
				
				IF NOT EXISTS (SELECT [CustomFieldValueID] FROM [dbo].[MaterialCustomFieldValueXREF]
								WHERE CustomFieldValueID = @OriginalCustomFieldValueID)
					BEGIN								
						UPDATE dbo.CustomFieldValue
							SET CustomFieldValueInUseFlag = 0,
								UpdateDT = GETDATE()
						FROM dbo.CustomFieldValue CFV 
						WHERE CFV.CustomFieldValueID = @OriginalCustomFieldValueID
					END

				UPDATE dbo.CustomFieldValue
					SET CustomFieldValueInUseFlag = 1
				WHERE CustomFieldValueID = @CustomFieldValueID

				END
		
		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =  'The row in MaterialCustomFieldValueXREF with MCFVID ' + CAST(@MCFVID AS varchar(10)) +  ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
		END
END

IF @@ERROR = 0
	SELECT @MCFVID AS MCFVID
GO

