@ODCTaskID varchar(3),
@ODCTaskTitle varchar(100),
@ODCTaskDescription  varchar(max),
@ODCMOQText varchar(max),
@BOEID int,
@UpdateDT datetime2,
@TaskStartDate date,
@TaskEndDate date,
@SortOrderID int
)
AS
/******************************************************************************
**		 
**		Name: [upsertODCTaskElement]
**		Desc: Insert/Update data into ODC Task Element Detailed Section of BOE/ODC
**			
**		
**
**		Auth: Don Canuso
