	INSERT INTO [dbo].[ODCTaskElementCustomFieldValueXREF]
           ([ODCTaskElementID]
           ,[CustomFieldValueID]
           ,[UpdateDT])
     OUTPUT inserted.OTECFVID INTO @InsertedODCTaskElementCustomFieldValue
     VALUES
           (
           @ODCTaskElementID,
           @CustomFieldValueID,
           @UpdateDT
           )
           
	SELECT @OTECFVID = OTECFVID FROM @InsertedODCTaskElementCustomFieldValue
	
	UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = 1
	WHERE CustomFieldValueID = @CustomFieldValueID
END

ELSE
	BEGIN
		IF (SELECT UpdateDT FROM [dbo].[ODCTaskElementCustomFieldValueXREF] WHERE OTECFVID = @OTECFVID) = @UpdateDT
		BEGIN
			SET @UpdateDT = GetDate()
			
			DECLARE @OriginalCustomFieldValueID int

			SELECT @OriginalCustomFieldValueID = CustomFieldValueID
			FROM dbo.ODCTaskElementCustomFieldValueXREF 
			WHERE OTECFVID = @OTECFVID
			
			UPDATE [dbo].[ODCTaskElementCustomFieldValueXREF]
				SET [CustomFieldValueID] = @CustomFieldValueID,
					[UpdateDT] = @UpdateDT
			WHERE OTECFVID = @OTECFVID


			IF @OriginalCustomFieldValueID <> @CustomFieldValueID
				BEGIN
				/*
				Only should be looking within the scope
				of the Custom Field, so if the scope is ODCType
				then only look in ODCTypeCustomFieldValueXREF
				
				Only need to set flag to 0 when last one
				*/
				
				IF NOT EXISTS (SELECT [CustomFieldValueID] FROM [dbo].[ODCTaskElementCustomFieldValueXREF]
								WHERE CustomFieldValueID = @OriginalCustomFieldValueID)
					BEGIN
						UPDATE dbo.CustomFieldValue
						SET CustomFieldValueInUseFlag = 0,
							UpdateDT = GETDATE()
						FROM dbo.CustomFieldValue CFV 
						WHERE CFV.CustomFieldValueID = @OriginalCustomFieldValueID
					END

				UPDATE dbo.CustomFieldValue
					SET CustomFieldValueInUseFlag = 1
				WHERE CustomFieldValueID = @CustomFieldValueID

				END

			


		
		END
	ELSE
		BEGIN
			DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =  'The row in ODCTaskElementCustomFieldValueXREF with OTECFVID ' + CAST(@OTECFVID AS varchar(10)) +  ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
		END
END

IF @@ERROR = 0
	SELECT @OTECFVID AS OTECFVID
GO

