			SELECT	/*@CurrentResourceID  = ResourceID,*/
					@CurrentPerformingOrganizationID = PerformingOrganizationID
			FROM [dbo].[ODCType]
			WHERE ODCTypeID = @ODCTypeID
			
			SET @UpdateDT = GetDate()
			
			UPDATE [dbo].[ODCType]
