CREATE PROCEDURE [dbo].[upsertUser]
(
@ETIUserID int,
@NTID varchar(1000),
@NTDomain varchar(10),
@DisplayName varchar(50),
@EmailAddress varchar(50),
@PhoneNumber varchar(20),
@FirstName varchar(25),
@LastName varchar(25),
@UpdateDT datetime2
)
AS
/******************************************************************************
**		 
**		Name: upsertUser
**		Desc: We add users via the Workspace Permissions section
**			
**		
**
**		Auth: Don Canuso
**		Date: June 2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/18/10		dcanuso				Deleted and Update Date added to ETI User Table, 
**											Group funcationality added, Update Date Added	
**		9/02/10		dcanuso				We are currently only adding users via 
**											Workspace Permissions  - Removing Group input as this
**											will be handled by Workspace Permissions
**		9/13/10		dcanuso				Soft deletes removed
**		2/17/11		dcanuso				FirstName and LastName added
**		5/9/11		dcanuso				Task 3364:ETIUser table - 
**										needs to be able to have duplicate ntid made unique by the domain
**										Checking for dup in SP
**		9/5/12		mbasquil			WI 10910 Added IsNull() checks to properly
**										handle null values	
**		11/21/13	dcanuso				User NTID Increased
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @InsertedETIUser AS Table (ETIUserID int)
DECLARE @ErrorMessage varchar (500)

IF @ETIUserID < 0 
	IF EXISTS (SELECT 1 FROM dbo.ETIuser 
				WHERE NTID = @NTID AND 
					  IsNull(NTDomain, 'null') = IsNull(@NTDomain, 'null')
			   )
				BEGIN

				SET @ErrorMessage =   'A row in ETIuser with NTID and NTDomain already exists'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
				END
	ELSE
		BEGIN

			SET @UpdateDT = GETDATE()

			INSERT INTO [dbo].[ETIuser]
				   ([NTID]
				   ,[NTDomain]
				   ,[DisplayName]
				   ,[EmailAddress]
				   ,[PhoneNumber]
				   ,[FirstName]
				   ,[LastName]
				   ,[UpdateDT])
			 OUTPUT inserted.ETIUserID INTO @InsertedETIUser
			 VALUES
				   (@NTID
				   ,@NTDomain
				   ,@DisplayName
				   ,@EmailAddress
				   ,@PhoneNumber
				   ,@FirstName
				   ,@LastName
				   ,@UpdateDT
				   )
		           
			  SELECT @ETIUserID = ETIUserID FROM @InsertedETIUser
									
		 END
ELSE
	BEGIN
	IF (SELECT UpdateDT FROM dbo.ETIuser WHERE ETIUserID = @ETIUserID) = @UpdateDT
		BEGIN 
			IF EXISTS (SELECT 1 FROM dbo.ETIuser 
						WHERE NTID = @NTID AND 
							  isNUll(NTDomain, 'null') = IsNull(@NTDomain, 'null') AND 
							  ETIUserID <> @ETIUserID
					   )
				BEGIN
					SET @ErrorMessage =   'A row in ETIuser with NTID and NTDomain already exists'
					RAISERROR (
						@ErrorMessage, -- Message text.
						11, -- Severity,/*Severity Changed to 11*/
						1 -- State,
						)
					RETURN
				END
			ELSE
				BEGIN
					SET @UpdateDT = GETDATE()
					UPDATE [dbo].[ETIuser]
					   SET	
							[NTDomain] = @NTDomain,
							[DisplayName] = @DisplayName,
							[EmailAddress] = @EmailAddress,
							[PhoneNumber] = @PhoneNumber,
							[FirstName] = @FirstName,
							[LastName] = @LastName,
							[UpdateDT] = @UpdateDT
					WHERE 
						[ETIUserID] = @ETIUserID
				END
		END		
	ELSE
			BEGIN
				SET @ErrorMessage =   'The row in ETIuser with ETIuserID ' + CAST(@ETIuserID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
			END
           			
	END

IF @@ERROR = 0
	SELECT @ETIUserID as ETIUserID
GO

