@WorkspaceRegionDTSID int,
@UpdateDT datetime2,
@WorkspaceID int,
@DTSRegionID int,
@DTSRegionPercentage decimal(6, 5),
@SegmentID int
)
AS
/******************************************************************************
**		 
**		Name: [upsertWorkspaceRegionDTS]
**		Desc: Assign a Region and DTS % to a Workspace 
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/25/11
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		8/31/11		dcanuso				Adding SegmentID to complete Wireframes
**		10/31/11	dcanuso				WI 5770 DTSRegionPercentage to decimal(6, 5)
*******************************************************************************/
SET NOCOUNT ON 

DECLARE	@Inserted AS Table (WorkspaceRegionDTSID int)

IF @WorkspaceRegionDTSID < 0  /*Insert Record*/

	BEGIN

	SET @UpdateDT = GetDate()

	INSERT INTO [dbo].[WorkspaceRegionDTS]
			   ([UpdateDT]
			   ,[WorkspaceID]
			   ,[DTSRegionID]
			   ,[DTSRegionPercentage]
			   ,[SegmentID])
     OUTPUT inserted.WorkspaceRegionDTSID INTO @Inserted
	 VALUES
			   (@UpdateDT
			   ,@WorkspaceID
			   ,@DTSRegionID
			   ,@DTSRegionPercentage
			   ,@SegmentID)

	SELECT 	@WorkspaceRegionDTSID = WorkspaceRegionDTSID FROM @Inserted
	
END

ELSE
	BEGIN
			IF (SELECT UpdateDT FROM dbo.WorkspaceRegionDTS WHERE WorkspaceRegionDTSID = @WorkspaceRegionDTSID) = @UpdateDT
			BEGIN	
			
			SET @UpdateDT = GetDate()
			
			UPDATE [dbo].[WorkspaceRegionDTS]
			   SET [UpdateDT] = @UpdateDT,
				   [WorkspaceID] = @WorkspaceID,
				   [DTSRegionID] = @DTSRegionID,
				   [DTSRegionPercentage] = @DTSRegionPercentage,
				   [SegmentID] = @SegmentID
			 WHERE WorkspaceRegionDTSID = @WorkspaceRegionDTSID

	END
			ELSE
			BEGIN
				DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in WorkspaceRegionDTS with WorkspaceRegionDTSID ' + CAST(@WorkspaceRegionDTSID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
			END
			
	END

IF @@ERROR = 0
	SELECT @WorkspaceRegionDTSID AS WorkspaceRegionDTSID
GO

