CREATE PROCEDURE [dbo].[upsertWorkspaceResourceRate]
(
@WorkspaceResourceRateID [int],
@UpdateDT [datetime2](7),
@WorkspaceID int,
@WorkspaceResourceID [int],
@WorkspaceResourceRateStartDate [date],
@WorkspaceResourceRateEndDate [date],
@WorkspaceResourceRate [decimal](5, 2),
@SystemResourceID int
)
AS
/******************************************************************************
**		 
**		Name: [upsertWorkspaceResourceRate]
**		Desc: Insert/Update data in Workspace Resource Rate 
**			
**		
**
**		Auth: Don Canuso
**		Date: 11/29/2011
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			---------------------------------------
**		12/15/11	dcanuso				WI 6103
**		12/29/11	dcanuso				WI 6579
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		1/17/12		dcanuso				Workspace Resource Rate table updated
*******************************************************************************/
SET NOCOUNT ON 

DECLARE	@Inserted AS Table (WorkspaceResourceRateID int)

IF @WorkspaceResourceRateID < 0  /*Insert Record*/
	BEGIN
		SET @UpdateDT = GetDate()

		INSERT INTO [dbo].[WorkspaceResourceRate]
			   ([UpdateDT]
			   ,[WorkspaceID]
			   ,[WorkspaceResourceID]
			   ,[WorkspaceResourceRateStartDate]
			   ,[WorkspaceResourceRateEndDate]
			   ,[WorkspaceResourceRate]
			   ,[SystemResourceID]
			   )
		 OUTPUT inserted.WorkspaceResourceRateID INTO @Inserted
		 VALUES
			   (@UpdateDT
			   ,@WorkspaceID
			   ,@WorkspaceResourceID
			   ,@WorkspaceResourceRateStartDate
			   ,@WorkspaceResourceRateEndDate
			   ,@WorkspaceResourceRate
			   ,@SystemResourceID
			   )

		SELECT 	@WorkspaceResourceRateID = WorkspaceResourceRateID FROM @Inserted
	END
ELSE
	BEGIN
			IF (SELECT UpdateDT FROM [dbo].[WorkspaceResourceRate] WHERE WorkspaceResourceRateID = @WorkspaceResourceRateID) = @UpdateDT
			BEGIN	
			
			/*Variables Used for InUse Function*/
			DECLARE	@CurrentResourceID int
			
			SELECT 	@CurrentResourceID  = SystemResourceID
			FROM  [dbo].[WorkspaceResourceRate]
			WHERE WorkspaceResourceRateID = @WorkspaceResourceRateID
			
			SET @UpdateDT = GetDate()

			UPDATE [dbo].[WorkspaceResourceRate]
			   SET [UpdateDT] = @UpdateDT
				  ,[WorkspaceResourceID] = @WorkspaceResourceID
				  ,[WorkspaceResourceRateStartDate] = @WorkspaceResourceRateStartDate
				  ,[WorkspaceResourceRateEndDate] = @WorkspaceResourceRateEndDate
				  ,[WorkspaceResourceRate] = @WorkspaceResourceRate
  				  ,[SystemResourceID] = @SystemResourceID
			 WHERE WorkspaceResourceRateID = @WorkspaceResourceRateID
		END
			ELSE
			BEGIN
				DECLARE @ErrorMessage varchar (500)
				SET @ErrorMessage =   'The row in WorkspaceResourceRate with WorkspaceResourceRateID ' + CAST(@WorkspaceResourceRateID  AS varchar(10)) + ' has been updated and is out of sync with the data in your browser.  Please refresh your data.'
				RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
				RETURN
			END
			
	END

IF @@ERROR = 0
	SELECT @WorkspaceResourceRateID AS WorkspaceResourceRateID
GO

