CREATE PROCEDURE [dbo].[updateBOELaborTypeviaTableParameter]
(
@BOELaborType [dbo].[TT_BOELaborType] READONLY
)
AS
/******************************************************************************
**		 
**		Name: upsertBOELaborType
**		Desc: Insert/Update data into Labor Type Section of BOE
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19		dcanuso				RETURN was not working properly - corrected
**		9/3			dcanuso				Added Reource, data type changes for spread
**										Removed:
**										@LaborTypeID int,
**										@SegmentRegionID int,
**										They are associated with a single Resource ID not a BOE
**		9/13/10		dcanuso				Soft deletes removed
**		12/14/10	dcanuso				Changed percent spread parameter to decimal (6,3)
**		1/20/11		dcanuso				Resource Redesign called for changes in SP
**		2/10/11		dcanuso				Adding InUse functionality for Resource and 
**										Performing Organization
**		2/14/11		dcanuso				Added Updating Update DT
**		5/26/11		dcanuso				Value Spread changed and added @SpreadTypeID
**		11/25/11	dcanuso				InUse Updated
**		12/13/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		2/6/12		dcanuso				More changes to InUse Processing
**		4/12/12		dcanuso				WI 8398 Locking Spread
**		8/3/12		dcanuso				WI 10410 % Spread to 38,12
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		8/9/12		dcanuso				WI 10410 changed @PercentSpread DECIMAL (38,3)
**		2/11/13		dcanuso				WI14842 Redesign Performing Organization
**		10/14/15	mbasquil			BOEJ-342 Resource level WBS/CLIN
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @UpdateDT datetime2(7) = GetDate()
			
UPDATE [dbo].[BOELaborType]
SET 
	[ResourceID] = T.ResourceID,
	[PerformingOrganizationID] = T.PerformingOrganizationID,
	[BOELaborTypeStartDate] = T.BOELaborTypeStartDate,
	[BOELaborTypeEndDate] = T.BOELaborTypeEndDate,
	[SpreadCurveID] = T.SpreadCurveID,
	[PercentSpread] = T.PercentSpread,
	[ValueSpread] = T.ValueSpread,
	[BOETaskElementID] = T.BOETaskElementID,
	[SpreadTypeID] = T.SpreadTypeID,
	[UpdateDT] = @UpdateDT,
	[PercentSpreadLocked] = T.PercentSpreadLocked,
	[HourSpreadLocked] = T.HourSpreadLocked,
	[WBSID]	= T.WBSID,
	[CLINID] = T.CLINID
FROM [dbo].[BOELaborType] L
	INNER JOIN @BOELaborType T ON 
		L.[BOELaborTypeID] = T.[BOELaborTypeID] AND
		L.[UpdateDT] = T.[UpdateDT] 
				
IF @@ERROR = 0
SELECT	L.BOELaborTypeID AS BOELaborTypeID,
		L.[UpdateDT]
FROM [dbo].[BOELaborType] L
	INNER JOIN @BOELaborType T ON 
		L.[BOELaborTypeID] = T.[BOELaborTypeID] 
ORDER BY T.OrderID
GO
CREATE PROCEDURE [dbo].[insertBOELaborTypeviatableParameter]
(
@BOELaborType [dbo].[TT_BOELaborType] READONLY
)
AS
/******************************************************************************
**		 
**		Name: upsertBOELaborType
**		Desc: Insert/Update data into Labor Type Section of BOE
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19		dcanuso				RETURN was not working properly - corrected
**		9/3			dcanuso				Added Reource, data type changes for spread
**										Removed:
**										@LaborTypeID int,
**										@SegmentRegionID int,
**										They are associated with a single Resource ID not a BOE
**		9/13/10		dcanuso				Soft deletes removed
**		12/14/10	dcanuso				Changed percent spread parameter to decimal (6,3)
**		1/20/11		dcanuso				Resource Redesign called for changes in SP
**		2/10/11		dcanuso				Adding InUse functionality for Resource and 
**										Performing Organization
**		2/14/11		dcanuso				Added Updating Update DT
**		5/26/11		dcanuso				Value Spread changed and added @SpreadTypeID
**		11/25/11	dcanuso				InUse Updated
**		12/13/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		2/6/12		dcanuso				More changes to InUse Processing
**		4/12/12		dcanuso				WI 8398 Locking Spread
**		8/3/12		dcanuso				WI 10410 % Spread to 38,12
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		8/9/12		dcanuso				WI 10410 changed @PercentSpread DECIMAL (38,3)
**		2/11/13		dcanuso				WI14842 Redesign Performing Organization
**		5/21/15	    Ray Frankson		BOE-J16 Added IFNULL checks to selection of result set so proper data is retuned.
**		9/28/15		dcanuso				Added some additional IsNulls
**		10/14/15	mbasquil			BOEJ-342 Resource level WBS/CLIN
*******************************************************************************/
SET NOCOUNT ON 

DECLARE @UpdateDT datetime2(7) = GetDate()

INSERT INTO [dbo].[BOELaborType]
           (
            [ResourceID]
           ,[PerformingOrganizationID]
           ,[BOELaborTypeStartDate]
           ,[BOELaborTypeEndDate]
           ,[SpreadCurveID]
           ,[PercentSpread]
           ,[ValueSpread]
           ,[BOETaskElementID]
           ,[SpreadTypeID]/*Spread Type is Labor and Hours
							to determine if the BOE Labor Type row
							is one of those types*/
           ,[UpdateDT]
           ,[PercentSpreadLocked]
           ,[HourSpreadLocked]
		   ,[WBSID]
		   ,[CLINID]
           )
SELECT 
       [ResourceID]
      ,[PerformingOrganizationID]
      ,[BOELaborTypeStartDate]
      ,[BOELaborTypeEndDate]
      ,[SpreadCurveID]
      ,[PercentSpread]
      ,[ValueSpread]
      ,[BOETaskElementID]
      ,[SpreadTypeID]
	  ,@UpdateDT
      ,[PercentSpreadLocked]
      ,[HourSpreadLocked]
	  ,[WBSID]
	  ,[CLINID]
FROM @BOELaborType
          

IF @@ERROR = 0         
BEGIN

DECLARE @Result TABLE
(
BOELaborTypeID int,
UpdateDT datetime2(7),
OrderID int
)

DECLARE @OrderID int = 0

WHILE EXISTS (SELECT * FROM @BOELaborType WHERE OrderID = @OrderID)
BEGIN
INSERT INTO @Result
SELECT TOP 1 B.BOELaborTypeID, B.UpdateDT, T.OrderID
/*
SELECT	B.BOELaborTypeID,
		B.UpdateDT,
		T.OrderID*/
FROM @BOELaborType T
	INNER JOIN [dbo].[BOELaborType] B ON 
      IsNull(T.[ResourceID], -99) = IsNull(B.ResourceID, -99) AND
      IsNull(T.[PerformingOrganizationID], -99) = IsNull(B.PerformingOrganizationID, -99) AND
      T.[BOELaborTypeStartDate] = B.[BOELaborTypeStartDate] AND
      T.[BOELaborTypeEndDate] = B.[BOELaborTypeEndDate] AND
      T.[SpreadCurveID] = B.[SpreadCurveID] AND
      IsNull(T.[PercentSpread], 0) = IsNull(B.[PercentSpread], 0) AND
      IsNull(T.[ValueSpread], 0) = IsNull(B.[ValueSpread], 0) AND
      T.[BOETaskElementID] = B.[BOETaskElementID] AND
      IsNull(T.[SpreadTypeID], -99) = IsNull(B.[SpreadTypeID], -99) AND
      T.[PercentSpreadLocked] = B.[PercentSpreadLocked] AND
      T.[HourSpreadLocked] = B.[HourSpreadLocked] AND 
	  ISNULL(T.[WBSID], 0) = ISNULL(B.[WBSID], 0) AND
	  ISNULL(T.[CLINID], 0) = ISNULL(B.[CLINID], 0) AND
	  T.OrderID = @OrderID AND 
	  B.BOELaborTypeID NOT IN	
					(
						SELECT BOELaborTypeID FROM @Result
					)
		WHERE B.UpdateDT = @UpdateDT	

	SET @OrderID = @OrderID + 1 
END
END

SELECT BOELaborTypeID, UpdateDT FROM @Result ORDER BY OrderID
GO

/*
    File: \Table Based Processing\OrdinaryVariableViaTable.sql
*/
PRINT '### Starting file: \Table Based Processing\OrdinaryVariableViaTable.sql';
-- Drop SPs first
IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[deleteBOETaskElementOrdinaryVariableviaTableParameter]') AND type in (N'P', N'PC'))
