		[TaskStartDate] = TT.TaskStartDate,
		[TaskEndDate] = TT.TaskEndDate,
		[MOQHoursEquation] = TT.MOQHoursEquation,
		[MOQCostEquation] = TT.MOQCostEquation,
		[MOQText] = TT.MOQText,
		[MOQTypeID] = TT.MOQTypeID,
		[BOEID] = TT.BOEID,
		[LaborTypeWarningFlag] = TT.LaborTypeWarningFlag,
		[IMS_ID] = TT.IMS_ID,
		[TaskElementTypeID] = TT.TaskElementTypeID,
		[UpdateDT] = @UpdateDT,
		[SortOrderID] = TT.SortOrderID
FROM [dbo].[BOETaskElement] TE
	INNER JOIN @BOETaskElement TT ON 
		TE.BOETaskElementID = TT.BOETaskElementID AND
		TE.UpdateDT = TT.UpdateDT
				
IF @@ERROR = 0
	SELECT 
		T.BOETaskElementID AS BOETaskElementID, 
		T.UpdateDT AS UpdateDT 
	FROM @BOETaskElement TT
		INNER JOIN dbo.BOETaskElement T ON TT.BOETaskElementID = T.BOETaskElementID
	ORDER BY OrderID
GO
CREATE PROCEDURE [dbo].[deleteBOETaskElementviaTableParameter]
(
@BOETaskElement [dbo].[TT_BOETaskElement] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [deleteBOETaskElementviaTableParameter]
**		Desc: Delete Flag set in LM Task Element Section of BOE and all sub-elements (Labor Types and Labor Spread)
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19/10		dcanuso				RETURN was not working properly - corrected
**		9/13/10		dcanuso				Soft deletes removed
**		10/6/10		dcanuso				Variables were added and need to be added
**		4/21/11		dcanuso				Added new tables that need DELETE statements
**		5/3/11		dcanuso				BOETaskElementMetricXREF added
**		7/20/11		dcanuso				Fixed the processing of In Use
**		8/18/11		dcanuso				Commented out extra In Use Processing
**										for BOE Custom Fields
**		8/31/11		dcansuo				Added OrdinaryVariableSumVariableResourceTypeXREF
**		12/15/11	dcanuso				WI 6166
**		12/21/11	dcanuso				WI 6021
**										Need to check if a Travel Resource Rate 
**										is being used/not used
**										and update accordingly
**		1/10/12		dcanuso				WI 
**										6470: Trip In Use Fixes
**										https://eureka.isgs.lmco.com/#activity/151789
**										6624: After WI 6622, we now need to check that 
**										the originating Labor Resource Rate is in 
**										use as we did for trips.
**										6339: Confirm in-use is working for workspace
**										and labor resource rates
**		8/7/12		dcanuso				WI 10278: Resource Redesign 
**										In Use will no longer be stored in DB
**		2/4/13		dcanuso				WI14842 Redesign Performing Organization
**		12/9/13		dcanuso				WI 24983 - BOE Task Elemet genData Metric XREF
**		8/27/14		dcanuso				Image Story
**		10/3/14		dcanuso				Image Story Removal
**		7/30/15		dcanuso				metric detail
*******************************************************************************/
SET NOCOUNT ON 


			DELETE FROM dbo.BOELaborSpread
				FROM dbo.BOELaborSpread LS
				INNER JOIN dbo.BOELaborType LT ON LS.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT
				
			
			DELETE FROM dbo.BOELaborTypeCustomFieldValueXREF
			FROM dbo.BOELaborTypeCustomFieldValueXREF X
				INNER JOIN dbo.BOELaborType LT ON X.BOELaborTypeID = LT.BOELaborTypeID
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT
				
				
			DELETE FROM dbo.BOETaskElementWorkspaceVariableXREF
			FROM dbo.BOETaskElementWorkspaceVariableXREF X  
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

				
			DELETE FROM dbo.SumOfBOE_OrdinaryVariableXREF
			FROM  dbo.SumOfBOE_OrdinaryVariableXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN  dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

			

			DELETE FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF
			FROM dbo.OrdinaryVariableSumVariableResourceTypeXREF X
				INNER JOIN dbo.OrdinaryVariable OV ON X.OrdinaryVariableID = OV.OrdinaryVariableID
				INNER JOIN  dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
							INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT


				

			DELETE FROM dbo.OrdinaryVariable
			FROM dbo.OrdinaryVariable OV
				INNER JOIN dbo.BOETaskElement TE ON OV.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

				
				
			DELETE FROM dbo.BOETaskElementCustomFieldValueXREF
			FROM dbo.BOETaskElementCustomFieldValueXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

			
			
			/*Table to check Metrics*/
			DECLARE @Metric TABLE (MetricID int)
			INSERT INTO @Metric 
			SELECT X.MetricID 
			FROM dbo.BOETaskElementMetricXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

			
			
			DELETE FROM dbo.BOETaskElementMetricXREF
				FROM dbo.BOETaskElementMetricXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT
		
				

			DELETE FROM dbo.BOETaskElementgenDataMetricXREF
				FROM dbo.BOETaskElementgenDataMetricXREF X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT
		


			DELETE FROM [dbo].[BOETaskElementMetricDetailXREF]
				FROM [dbo].[BOETaskElementMetricDetailXREF] X 
				INNER JOIN dbo.BOETaskElement TE ON X.BOETaskElementID = TE.BOETaskElementID 
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT


			/*
			Now that the BOETaskElementMetricXREF has been deleted
			
			Check if Metric is still In Use
			*/
			UPDATE [dbo].[Metric]
				SET [MetricInUse] =	
					CASE
						WHEN X.MetricID IS NULL THEN 0
						ELSE 1 /*In Use*/
					END
				FROM  [dbo].[Metric] M
				INNER JOIN @Metric tM ON M.MetricID = tM.MetricID 
				/*Only Need to check the deleted list*/
					LEFT OUTER JOIN dbo.BOETaskElementMetricXREF X ON M.MetricID = X.MetricID

			
	
			
 
			DELETE FROM dbo.BOELaborType
				FROM dbo.BOELaborType LT
				INNER JOIN dbo.BOETaskElement TE ON LT.BOETaskElementID = TE.BOETaskElementID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT

				
				
			DECLARE @WorkspaceID int
			SELECT @WorkspaceID = WorkspaceID 
			FROM dbo.BOE B
				INNER JOIN dbo.BOETaskElement TE ON B.BOEID = TE.BOEID
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT


			
				
			DELETE FROM [dbo].[BOETaskElement]
			FROM [dbo].[BOETaskElement] TE
				INNER JOIN @BOETaskElement TT ON 
					TE.BOETaskElementID = TT.BOETaskElementID AND
					TE.UpdateDT = TT.UpdateDT




/*
Fix All In Use Flags
*/
/*Check if Resource is used elsewhere*/
/*EXECUTE [dbo].[updateResourceInUseFlagByWorkspaceID] @WorkspaceID*/



/*Check if PerformingOrganization is used elsewhere*/
/*EXECUTE [dbo].[updatePerformingOrganizationInUseFlagByWorkspaceID] @WorkspaceID*/
		
/*
Not needed as we are not deleting or changing data in BOECustomFieldValueXREF

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = CASE 
										WHEN X.[CustomFieldValueID] IS NULL THEN 0
										WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
									END,
		UpdateDT = GETDATE()
FROM dbo.CustomFieldValue CFV 
	INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
	LEFT OUTER JOIN [dbo].[BOECustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CF.WorkspaceID = @WorkspaceID
*/

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = CASE 
										WHEN X.[CustomFieldValueID] IS NULL THEN 0
										WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
									END,
		UpdateDT = GETDATE()
FROM dbo.CustomFieldValue CFV 
	INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
	LEFT OUTER JOIN [dbo].[BOELaborTypeCustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CF.WorkspaceID = @WorkspaceID

UPDATE dbo.CustomFieldValue
	SET CustomFieldValueInUseFlag = CASE 
										WHEN X.[CustomFieldValueID] IS NULL THEN 0
										WHEN X.[CustomFieldValueID] IS NOT NULL THEN 1
									END,
		UpdateDT = GETDATE()
FROM dbo.CustomFieldValue CFV 
	INNER JOIN dbo.CustomField CF ON CFV.CustomFieldID = CF.CustomFieldID
	LEFT OUTER JOIN [dbo].[BOETaskElementCustomFieldValueXREF] X ON
		CFV.[CustomFieldValueID] = X.[CustomFieldValueID]
WHERE 
	CF.WorkspaceID = @WorkspaceID				





IF @@ERROR <> 0
BEGIN
DECLARE @ErrorMessage varchar (500)
SET @ErrorMessage =   'The row(s) in BOETaskElement has been updated and is out of sync with the data in your browser.  Please refresh your data.'
			RAISERROR (
					@ErrorMessage, -- Message text.
			        11, -- Severity,/*Severity Changed to 11*/
					1 -- State,
					)
			RETURN
 
		END
GO
CREATE PROCEDURE [dbo].[insertBOETaskElementviaTableParameter]
(
@BOETaskElement [dbo].[TT_BOETaskElement] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [upsertBOETaskElement]
**		Desc: Insert/Update data into BOE Task Elements Detailed Section of BOE
**			
**		
**
**		Auth: Don Canuso
**		Date: 8/2010
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**		--------	--------			-------------------------------------------
**		8/19		dcanuso				RETURN was not working properly - corrected
**		9/13/10		dcanuso				Soft deletes removed
**		9/17/10		dcanuso				Additional database changes caused 
**		3/23/11		dcanuso				Developer request to add LaborTypeWarningFlag
**		3/28/11		dcanuso				New Parameter added for IMS Importing
**		3/29/11		dcanuso				Removing @DataSource - now in BOE
**		4/18/11		dcanuso				Adding MetricID to support Historical Metrics
**										MOQ Text changed from max to 8000
**		5/3/11		dcanuso				Moving Metric to its own SP 
**		5/25/11		dcanuso				Changes:
**										@MOQHoursEquation varchar(250),
**										@MOQCostEquation varchar(250),
**										@CostElementID int
**		6/13/11		dcanuso				Cost Element removed and TaskElementTypeID added
**		3/5/13		dcanuso				WI 16730 moq text to varchar (max)
**		10/8/14		dcanuso				sorting story
*******************************************************************************/
SET NOCOUNT ON 
DECLARE @UpdateDT datetime2 = GETDATE()

DECLARE @TT_BOETaskElement TABLE
(
	[BOETaskElementID] [int] NOT NULL,
	[UpdateDT] [datetime2](7) NOT NULL,
	[TaskID] [varchar](3) NULL,
	[TaskTitle] [varchar](100) NOT NULL,
	[TaskDescription] [varchar](max) NULL,
	[TaskStartDate] [date] NULL,
	[TaskEndDate] [date] NULL,
	[MOQHoursEquation] [varchar](250) NULL,
	[MOQCostEquation] [varchar](250) NULL,
	[MOQText] [varchar](max) NULL,
	[MOQTypeID] [int] NULL,
	[BOEID] [int] NOT NULL,
	[LaborTypeWarningFlag] [bit] NOT NULL,
	[IMS_ID] [varchar](20) NULL,
	[TaskElementTypeID] [int] NOT NULL,
	[SortOrderID]  [int] NOT NULL,
	[OrderID] [int] NOT NULL
)
INSERT INTO @TT_BOETaskElement
SELECT * FROM @BOETaskElement







DECLARE @BOETaskElementID [int],
	@TaskID [varchar](3),
	@TaskTitle [varchar](100),
	@TaskDescription[varchar](max),
	@TaskStartDate [date],
	@TaskEndDate [date],
	@MOQHoursEquation [varchar](250),
	@MOQCostEquation [varchar](250),
	@MOQText [varchar](max),
	@MOQTypeID [int],
	@BOEID [int],
	@LaborTypeWarningFlag [bit],
	@IMS_ID [varchar](20),
	@TaskElementTypeID [int],
	@OrderID [int],
	@SortOrderID [int]


DECLARE @InsertedBOETaskElement AS Table (BOETaskElementID int)


WHILE EXISTS (SELECT * FROM @TT_BOETaskElement WHERE BOETaskElementID = -1)
BEGIN
	SELECT TOP 1 
     	@BOETaskElementID = BOETaskElementID,
		@TaskID = TaskID,
		@TaskTitle = TaskTitle,
		@TaskDescription = TaskDescription,
		@TaskStartDate = TaskStartDate,
		@TaskEndDate = TaskEndDate,
		@MOQHoursEquation = MOQHoursEquation,
		@MOQCostEquation = MOQCostEquation,
		@MOQText = MOQText,
		@MOQTypeID = MOQTypeID,
		@BOEID = BOEID,
		@LaborTypeWarningFlag = LaborTypeWarningFlag,
		@IMS_ID = IMS_ID,
		@TaskElementTypeID = TaskElementTypeID,
		@OrderID =  OrderID,
		@SortOrderID = SortOrderID
	FROM @TT_BOETaskElement
	WHERE BOETaskElementID = -1





	INSERT INTO [dbo].[BOETaskElement]
           ([TaskID]
           ,[TaskTitle]
           ,[TaskDescription]
           ,[TaskStartDate]
           ,[TaskEndDate]
           ,[MOQHoursEquation]
           ,[MOQCostEquation]
           ,[MOQText]
           ,[MOQTypeID]
           ,[BOEID]
           ,[LaborTypeWarningFlag]
           ,[IMS_ID]
           ,[TaskElementTypeID]
           ,[UpdateDT]
		   ,[SortOrderID]
		   )
     OUTPUT inserted.BOETaskElementID INTO @InsertedBOETaskElement
     VALUES
           (
            @TaskID
           ,@TaskTitle
           ,@TaskDescription
           ,@TaskStartDate
           ,@TaskEndDate
           ,@MOQHoursEquation
           ,@MOQCostEquation
           ,@MOQText
           ,@MOQTypeID
           ,@BOEID
           ,@LaborTypeWarningFlag
           ,@IMS_ID
           ,@TaskElementTypeID
           ,@UpdateDT
		   ,@SortOrderID
            ) 


            
	SELECT @BOETaskElementID = BOETaskElementID FROM @InsertedBOETaskElement


	
	UPDATE @TT_BOETaskElement
		SET BOETaskElementID = @BOETaskElementID
	WHERE 
		@OrderID = OrderID AND
		BOETaskElementID = -1

END


IF @@ERROR = 0
	SELECT 
		TT.BOETaskElementID AS BOETaskElementID, 
		@UpdateDT AS UpdateDT
	FROM @TT_BOETaskElement TT
		ORDER BY OrderID
GO

/*
    File: \Table Based Processing\TaskElementWorkspaceVariableViaTable.sql
*/
PRINT '### Starting file: \Table Based Processing\TaskElementWorkspaceVariableViaTable.sql';
-- Drop SPs first
IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[insertBOETaskElementWorkspaceVariableviaTableParameter]') AND type in (N'P', N'PC'))
	DROP PROCEDURE [dbo].[insertBOETaskElementWorkspaceVariableviaTableParameter];
GO

-- Drop types 2nd
IF  EXISTS (SELECT * FROM sys.types st JOIN sys.schemas ss ON st.schema_id = ss.schema_id WHERE st.name = N'TT_BOETaskElementWorkspaceVariableXREF' AND ss.name = N'dbo')
	DROP TYPE [dbo].[TT_BOETaskElementWorkspaceVariableXREF];
GO

-- Recreate types 3rd
CREATE TYPE [dbo].[TT_BOETaskElementWorkspaceVariableXREF] AS TABLE(
	[BOETaskWSVarID] [int] NOT NULL,
	[BOETaskElementID] [int] NOT NULL,
	[WorkspaceVariableID] [int] NOT NULL,
	[OrderID] [int] NOT NULL
);
GO

-- Recreate SPs last
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[insertBOETaskElementWorkspaceVariableviaTableParameter]
(
@BOETaskElementWorkspaceVariableXREF [dbo].[TT_BOETaskElementWorkspaceVariableXREF] READONLY
)
AS
/******************************************************************************
**		 
**		Name: [insertBOETaskElementWorkspaceVariable]
**		Desc:	Inserts Workspace Variable data into BOE Task Element
**				Handles Deletes
**				No Updates required
**			
**		
**
**		Auth: Don Canuso
**		Date: 11/15/10
*******************************************************************************
**		Change History
*******************************************************************************
**		Date:		Author:				Description:
**      6/4/15      dpalider            BOEJ-126 -> Fix bulk update SPs to handle 
**                                      missing data (moved the ORDER BY OrderID)
**      9/10/15     dpalider			BOEJ-338 -> Fix WS variables not being unlinked 
**										correctly
*******************************************************************************/
SET NOCOUNT ON 

/*Deletes*/
DELETE FROM dbo.BOETaskElementWorkspaceVariableXREF
	FROM dbo.BOETaskElementWorkspaceVariableXREF BW
		LEFT OUTER JOIN @BOETaskElementWorkspaceVariableXREF WS ON 
			BW.WorkspaceVariableID = WS.WorkspaceVariableID AND
			BW.BOETaskElementID = WS.BOETaskElementID
	WHERE	
		BW.BOETaskElementID IN (SELECT DISTINCT BOETaskElementID FROM @BOETaskElementWorkspaceVariableXREF) /* ONLY WANT TO AFFECT BOE TASK ELEMENTS BEING PASSED IN */
		AND BW.BOETaskWSVarID IS NOT NULL /* IN CURRENT TABLE */
		AND WS.BOETaskWSVarID IS NULL /* NO LONGER IN THE LIST SO DELETED */
	
/*INSERT*/		
INSERT INTO [dbo].[BOETaskElementWorkspaceVariableXREF] ([BOETaskElementID],[WorkspaceVariableID])
	SELECT WS.BOETaskElementID, WS.WorkspaceVariableID
		FROM @BOETaskElementWorkspaceVariableXREF WS
			LEFT OUTER JOIN dbo.BOETaskElementWorkspaceVariableXREF BW ON 
					WS.WorkspaceVariableID = BW.WorkspaceVariableID 
					AND WS.BOETaskElementID = BW.BOETaskElementID
		WHERE	
			BW.WorkspaceVariableID IS NULL /* NOT IN THE CURRENT TABLE */
			AND WS.WorkspaceVariableID <> -100 /* IN THE NEW LIST SO ADDED, AND NOT -100, WHICH INDICATES 0 VARIABLES BEING USED */
			AND WS.BOETaskWSVarID < 0 /* New Records have a value of negative */
		ORDER BY OrderID

IF @@ERROR = 0
SELECT BW.[BOETaskWSVarID]
	FROM [dbo].[BOETaskElementWorkspaceVariableXREF] BW
		INNER JOIN @BOETaskElementWorkspaceVariableXREF WS ON 
			BW.WorkspaceVariableID = WS.WorkspaceVariableID AND
			BW.BOETaskElementID = WS.BOETaskElementID
;
GO
PRINT '###### SCRIPT FINISHED ######';